    nc=len(planes)
    if samp is None: samp=[(1,1)]*nc
    hmax=max(s[0] for s in samp); vmax=max(s[1] for s in samp)
    mcux=(width+8*hmax-1)//(8*hmax); mcuy=(height+8*vmax-1)//(8*vmax)
    if qtables is None:
        qtables=[scale_q(STD_LUM_Q,quality), scale_q(STD_CHR_Q,quality)]
