static void fill_input(jdec *d)
{
  size_t n = fread(d->buf, 1, sizeof(d->buf), d->in);
  if (n == 0) {
    if (d->start_of_file)
      jd_error(d, "Empty input file");
    jd_warn(d, "Premature end of JPEG file");
    d->buf[0] = 0xFF;
    d->buf[1] = M_EOI;
    n = 2;
  }
  d->pos = 0;
  d->len = n;
  d->start_of_file = 0;
}

static int read_byte(jdec *d)
{
  if (d->pos >= d->len)
    fill_input(d);
  return d->buf[d->pos++];
}

static unsigned read_2bytes(jdec *d)
{
  unsigned a = (unsigned)read_byte(d);
  unsigned b = (unsigned)read_byte(d);
  return (a << 8) | b;
}

static void skip_input(jdec *d, long n)
{
  if (n <= 0)
    return;
  while (n > (long)(d->len - d->pos)) {
    n -= (long)(d->len - d->pos);
    d->pos = d->len;
    fill_input(d);
  }
  d->pos += (size_t)n;
}

/* ------------------------------------------------------------------ */
/* markers                                                              */

static void first_marker(jdec *d)
{
  int c = read_byte(d);
  int c2 = read_byte(d);
  if (c != 0xFF || c2 != M_SOI)
    jd_error(d, "Not a JPEG file: starts with 0x%02x 0x%02x", c, c2);
  d->unread_marker = c2;
}

static void next_marker(jdec *d)
{
  int c;
  for (;;) {
    c = read_byte(d);
    while (c != 0xFF) {
      d->discarded_bytes++;
      c = read_byte(d);
    }
    do {
      c = read_byte(d);
    } while (c == 0xFF);
    if (c != 0)
      break;
    d->discarded_bytes += 2;
  }
  if (d->discarded_bytes != 0) {
    jd_warn(d, "Corrupt JPEG data: %u extraneous bytes before marker 0x%02x",
            d->discarded_bytes, c);
    d->discarded_bytes = 0;
  }
  d->unread_marker = c;
}

static int saw_soi;

static void get_soi(jdec *d)
{
  if (saw_soi)
    jd_error(d, "Invalid JPEG file structure: two SOI markers");
  d->restart_interval = 0;
  d->saw_jfif = 0;
  d->saw_adobe = 0;
  d->adobe_transform = 0;
  saw_soi = 1;
}

static void get_sof(jdec *d, int prog, int arith)
{
  unsigned length;
  int i;
  d->progressive = prog;
  d->arith = arith;
  length = read_2bytes(d);
  d->precision = read_byte(d);
  d->height = (int)read_2bytes(d);
  d->width = (int)read_2bytes(d);
  d->ncomp = read_byte(d);
  length -= 8;
  if (d->saw_sof)
    jd_error(d, "Invalid JPEG file structure: two SOF markers");
  if (d->height <= 0 || d->width <= 0 || d->ncomp <= 0)
    jd_error(d, "Empty JPEG image (DNL not supported)");
  if (length != (unsigned)(d->ncomp * 3))
    jd_error(d, "Bogus marker length");
  if (d->ncomp > JD_MAXCOMP)
    jd_error(d, "Too many color components: %d, max %d", d->ncomp, 10);
  for (i = 0; i < d->ncomp; i++) {
    int c;
    d->comp[i].id = read_byte(d);
    c = read_byte(d);
    d->comp[i].h = (c >> 4) & 15;
    d->comp[i].v = c & 15;
    d->comp[i].tq = read_byte(d);
  }
  d->saw_sof = 1;
}

static void get_sos(jdec *d)
{
  unsigned length;
  int n, i, c;
  if (!d->saw_sof)
    jd_error(d, "Invalid JPEG file structure: SOS before SOF");
  length = read_2bytes(d);
  n = read_byte(d);
  if (length != (unsigned)(n * 2 + 6) || n < 1 || n > 4)
    jd_error(d, "Bogus marker length");
  d->scan_ncomp = n;
  for (i = 0; i < n; i++) {
    int cc = read_byte(d);
    int ci, pi;
    c = read_byte(d);
    for (ci = 0; ci < d->ncomp; ci++) {
      if (cc == d->comp[ci].id)
        break;
    }
    if (ci >= d->ncomp)
      jd_error(d, "Invalid component ID %d in SOS", cc);
    for (pi = 0; pi < i; pi++)
      if (d->scan_comp[pi] == ci)
        jd_error(d, "Invalid component ID %d in SOS", cc);
    d->scan_comp[i] = ci;
    d->comp[ci].td = (c >> 4) & 15;
    d->comp[ci].ta = c & 15;
  }
  d->Ss = read_byte(d);
  d->Se = read_byte(d);
  c = read_byte(d);
  d->Ah = (c >> 4) & 15;
  d->Al = c & 15;
  d->next_restart_num = 0;
}

static void get_dht(jdec *d)
{
  long length = (long)read_2bytes(d) - 2;
  while (length > 16) {
    int index = read_byte(d);
    uint8_t bits[17];
    uint8_t vals[256];
    int count = 0, i;
    jd_huff *h;
    bits[0] = 0;
    for (i = 1; i <= 16; i++) {
      bits[i] = (uint8_t)read_byte(d);
      count += bits[i];
    }
    length -= 1 + 16;
    if (count > 256 || (long)count > length)
      jd_error(d, "Bogus Huffman table definition");
    for (i = 0; i < count; i++)
      vals[i] = (uint8_t)read_byte(d);
    memset(&vals[count], 0, (size_t)(256 - count));
    length -= count;
    if (index & 0x10) {
      index -= 0x10;
      if (index < 0 || index >= 4)
        jd_error(d, "Bogus DHT index %d", index);
      h = &d->ac_tab[index];
    } else {
      if (index < 0 || index >= 4)
        jd_error(d, "Bogus DHT index %d", index);
      h = &d->dc_tab[index];
    }
    memcpy(h->bits, bits, sizeof(bits));
    memcpy(h->vals, vals, sizeof(vals));
    h->defined = 1;
  }
  if (length != 0)
    jd_error(d, "Bogus marker length");
}

static void get_dqt(jdec *d)
{
  long length = (long)read_2bytes(d) - 2;
  while (length > 0) {
    int n = read_byte(d);
    int prec = n >> 4;
    int i;
    n &= 0x0F;
    if (n >= 4)
      jd_error(d, "Bogus DQT index %d", n);
    for (i = 0; i < 64; i++) {
      unsigned tmp;
      if (prec)
        tmp = read_2bytes(d);
      else
        tmp = (unsigned)read_byte(d);
      d->qtab[n][natural_order[i]] = (uint16_t)tmp;
    }
    d->qtab_defined[n] = 1;
    length -= 64 + 1;
    if (prec)
      length -= 64;
  }
  if (length != 0)
    jd_error(d, "Bogus marker length");
}

static void get_dri(jdec *d)
{
  unsigned length = read_2bytes(d);
  if (length != 4)
    jd_error(d, "Bogus marker length");
  d->restart_interval = (int)read_2bytes(d);
}

static void get_interesting_appn(jdec *d, int marker)
{
  long length = (long)read_2bytes(d) - 2;
  uint8_t b[14];
  unsigned numtoread, i;
  if (length >= 14)
    numtoread = 14;
  else if (length > 0)
    numtoread = (unsigned)length;
  else
    numtoread = 0;
  for (i = 0; i < numtoread; i++)
    b[i] = (uint8_t)read_byte(d);
  length -= numtoread;
  if (marker == M_APP0) {
    if (numtoread >= 14 && b[0] == 0x4A && b[1] == 0x46 && b[2] == 0x49 &&
        b[3] == 0x46 && b[4] == 0) {
      d->saw_jfif = 1;
      if (b[5] != 1)
        jd_warn(d, "Warning: unknown JFIF revision number %d.%02d", b[5], b[6]);
    }
  } else {
    if (numtoread >= 12 && b[0] == 0x41 && b[1] == 0x64 && b[2] == 0x6F &&
        b[3] == 0x62 && b[4] == 0x65) {
      d->saw_adobe = 1;
      d->adobe_transform = b[11];
    }
  }
  if (length > 0)
    skip_input(d, length);
}

static void skip_variable(jdec *d)
{
  long length = (long)read_2bytes(d) - 2;
  if (length > 0)
    skip_input(d, length);
}

/* returns 1 when SOS reached, 2 when EOI reached */
static int read_markers(jdec *d)
{
  for (;;) {
    if (d->unread_marker == 0) {
      if (!saw_soi)
        first_marker(d);
      else
        next_marker(d);
    }
    switch (d->unread_marker) {
    case M_SOI:
      get_soi(d);
      break;
    case M_SOF0:
    case M_SOF1:
      get_sof(d, 0, 0);
      break;
    case M_SOF2:
      get_sof(d, 1, 0);
      break;
    case M_SOF9:
      get_sof(d, 0, 1);
      break;
    case M_SOF10:
      get_sof(d, 1, 1);
      break;
    case M_SOF3: case M_SOF5: case M_SOF6: case M_SOF7: case M_JPG:
    case M_SOF11: case M_SOF13: case M_SOF14: case M_SOF15:
      jd_error(d, "Unsupported JPEG process: SOF type 0x%02x", d->unread_marker);
    case M_SOS:
      get_sos(d);
      d->unread_marker = 0;
      return 1;
    case M_EOI:
      d->unread_marker = 0;
      return 2;
    case M_DAC:
      skip_variable(d);
      break;
    case M_DHT:
      get_dht(d);
      break;
    case M_DQT:
      get_dqt(d);
      break;
    case M_DRI:
      get_dri(d);
      break;
    case M_APP0:
    case M_APP14:
      get_interesting_appn(d, d->unread_marker);
      break;
    case 0xe1: case 0xe2: case 0xe3: case 0xe4: case 0xe5: case 0xe6:
    case 0xe7: case 0xe8: case 0xe9: case 0xea: case 0xeb: case 0xec:
    case 0xed: case 0xef: case M_COM:
      skip_variable(d);
      break;
    case 0xd0: case 0xd1: case 0xd2: case 0xd3: case 0xd4: case 0xd5:
    case 0xd6: case 0xd7: case M_TEM:
      break;
    case M_DNL:
      skip_variable(d);
      break;
    default:
      jd_error(d, "Unsupported marker type 0x%02x", d->unread_marker);
    }
    d->unread_marker = 0;
  }
}

/* ------------------------------------------------------------------ */
/* huffman decoding                                                     */

static void make_derived(jdec *d, jd_huff *h, int isdc)
{
  int huffsize[257];
  unsigned huffcode[257];
  int p, l, i, si, numsymbols;
  unsigned code;
  if (!h->defined)
    jd_error(d, "Huffman table 0x%02x was not defined", 0);
  p = 0;
  for (l = 1; l <= 16; l++) {
    i = h->bits[l];
    if (p + i > 256)
      jd_error(d, "Bogus Huffman table definition");
    while (i--)
      huffsize[p++] = l;
  }
  huffsize[p] = 0;
  numsymbols = p;
  code = 0;
  si = huffsize[0];
  p = 0;
  while (huffsize[p]) {
    while (huffsize[p] == si) {
      huffcode[p++] = code;
      code++;
    }
    if ((long)code >= (1L << si))
      jd_error(d, "Bogus Huffman table definition");
    code <<= 1;
    si++;
  }
  p = 0;
  for (l = 1; l <= 16; l++) {
    if (h->bits[l]) {
      h->valoffset[l] = (int32_t)p - (int32_t)huffcode[p];
      p += h->bits[l];
      h->maxcode[l] = (int32_t)huffcode[p - 1];
    } else {
      h->maxcode[l] = -1;
    }
  }
  h->valoffset[17] = 0;
  h->maxcode[17] = 0xFFFFF;
  if (isdc) {
    for (i = 0; i < numsymbols; i++) {
      if (h->vals[i] > 15)
        jd_error(d, "Bogus Huffman table definition");
    }
  }
}

#define BIT_BUF_SIZE 64
#define MIN_GET_BITS (BIT_BUF_SIZE - 7)

static uint64_t gbuf;

static void fill_bits(jdec *d, int nbits)
{
  if (d->unread_marker == 0) {
    while (d->bits_left < MIN_GET_BITS) {
      int c = read_byte(d);
      if (c == 0xFF) {
        do {
          c = read_byte(d);
        } while (c == 0xFF);
        if (c == 0) {
          c = 0xFF;
        } else {
          d->unread_marker = c;
          goto no_more;
        }
      }
      gbuf = (gbuf << 8) | (uint64_t)c;
      d->bits_left += 8;
    }
    return;
  }
no_more:
  if (nbits > d->bits_left) {
    if (!d->insufficient) {
      jd_warn(d, "Corrupt JPEG data: premature end of data segment");
      d->insufficient = 1;
    }
    gbuf <<= MIN_GET_BITS - d->bits_left;
    d->bits_left = MIN_GET_BITS;
  }
}

static inline int get_bits(jdec *d, int n)
{
  if (d->bits_left < n)
    fill_bits(d, n);
  d->bits_left -= n;
  return (int)((gbuf >> d->bits_left) & ((1u << n) - 1));
}

static int huff_decode(jdec *d, jd_huff *h)
{
  int l = 1;
  int32_t code = get_bits(d, 1);
  while (code > h->maxcode[l]) {
    code <<= 1;
    code |= get_bits(d, 1);
    l++;
  }
  if (l > 16) {
    jd_warn(d, "Corrupt JPEG data: bad Huffman code");
    return 0;
  }
  return h->vals[(int)(code + h->valoffset[l])];
}

static inline int huff_extend(int r, int s)
{
  return r < (1 << (s - 1)) ? r + (int)((unsigned)-1 << s) + 1 : r;
}

static void read_restart_marker(jdec *d);

static void process_restart(jdec *d)
{
  int ci;
  d->discarded_bytes += (unsigned)(d->bits_left / 8);
  d->bits_left = 0;
  read_restart_marker(d);
  for (ci = 0; ci < d->ncomp; ci++) {
    d->comp[ci].last_dc = 0;
    d->comp[ci].eobrun = 0;
  }
  d->restarts_to_go = d->restart_interval;
  if (d->unread_marker == 0)
    d->insufficient = 0;
}

static void resync_to_restart(jdec *d, int desired)
{
  int marker = d->unread_marker;
  int action;
  jd_warn(d, "Corrupt JPEG data: found marker 0x%02x instead of RST%d", marker, desired);
  for (;;) {
    if (marker < M_SOF0)
      action = 2;
    else if (marker < M_RST0 || marker > M_RST7)
      action = 3;
    else {
      if (marker == (M_RST0 + ((desired + 1) & 7)) ||
          marker == (M_RST0 + ((desired + 2) & 7)))
        action = 3;
      else if (marker == (M_RST0 + ((desired - 1) & 7)) ||
               marker == (M_RST0 + ((desired - 2) & 7)))
        action = 2;
      else
        action = 1;
    }
    switch (action) {
    case 1:
      d->unread_marker = 0;
      return;
    case 2:
      next_marker(d);
      marker = d->unread_marker;
      break;
    default:
      return;
    }
  }
}

static void read_restart_marker(jdec *d)
{
  if (d->unread_marker == 0)
    next_marker(d);
  if (d->unread_marker == M_RST0 + d->next_restart_num) {
    d->unread_marker = 0;
  } else {
    resync_to_restart(d, d->next_restart_num);
  }
  d->next_restart_num = (d->next_restart_num + 1) & 7;
}

/* ------------------------------------------------------------------ */
/* IDCT (accurate integer method)                                       */

#define CONST_BITS 13
#define PASS1_BITS 2
#define FIX_0_298631336 ((int64_t)2446)
#define FIX_0_390180644 ((int64_t)3196)
#define FIX_0_541196100 ((int64_t)4433)
#define FIX_0_765366865 ((int64_t)6270)
#define FIX_0_899976223 ((int64_t)7373)
#define FIX_1_175875602 ((int64_t)9633)
#define FIX_1_501321110 ((int64_t)12299)
#define FIX_1_847759065 ((int64_t)15137)
#define FIX_1_961570560 ((int64_t)16069)
#define FIX_2_053119869 ((int64_t)16819)
#define FIX_2_562915447 ((int64_t)20995)
#define FIX_3_072711026 ((int64_t)25172)
#define DESCALE(x, n) (((x) + ((int64_t)1 << ((n)-1))) >> (n))

static uint8_t range_table[5 * 256 + 128];
static uint8_t *sample_range_limit; /* limit[x] for x in -256..511 */
static uint8_t *idct_limit;

static void prepare_range_limit(void)
{
  uint8_t *table = range_table;
  int i;
  table += 256;
  sample_range_limit = table;
  memset(table - 256, 0, 256);
  for (i = 0; i <= 255; i++)
    table[i] = (uint8_t)i;
  table += 128;
  for (i = 128; i < 512; i++)
    table[i] = 255;
  memset(table + 512, 0, 512 - 128);
  memcpy(table + 1024 - 128, sample_range_limit, 128);
  idct_limit = sample_range_limit + 128;
}

static void idct_islow(const int16_t *coef, const uint16_t *q, uint8_t *out, int stride)
{
  int64_t tmp0, tmp1, tmp2, tmp3, tmp10, tmp11, tmp12, tmp13;
  int64_t z1, z2, z3, z4, z5;
  int ws[64];
  int ctr;
  const int16_t *in = coef;
  const uint16_t *qp = q;
  int *wp = ws;
  uint8_t *rl = idct_limit;

  for (ctr = 8; ctr > 0; ctr--) {
    if (in[8] == 0 && in[16] == 0 && in[24] == 0 && in[32] == 0 &&
        in[40] == 0 && in[48] == 0 && in[56] == 0) {
      int dcval = (int)(((int)in[0] * (int)qp[0]) * (1 << PASS1_BITS));
      wp[0] = wp[8] = wp[16] = wp[24] = wp[32] = wp[40] = wp[48] = wp[56] = dcval;
      in++; qp++; wp++;
      continue;
    }
    z2 = (int64_t)in[16] * qp[16];
    z3 = (int64_t)in[48] * qp[48];
    z1 = (z2 + z3) * FIX_0_541196100;
    tmp2 = z1 + z3 * (-FIX_1_847759065);
    tmp3 = z1 + z2 * FIX_0_765366865;
    z2 = (int64_t)in[0] * qp[0];
    z3 = (int64_t)in[32] * qp[32];
    tmp0 = (z2 + z3) * (1 << CONST_BITS);
    tmp1 = (z2 - z3) * (1 << CONST_BITS);
    tmp10 = tmp0 + tmp3;
    tmp13 = tmp0 - tmp3;
    tmp11 = tmp1 + tmp2;
    tmp12 = tmp1 - tmp2;

    tmp0 = (int64_t)in[56] * qp[56];
    tmp1 = (int64_t)in[40] * qp[40];
    tmp2 = (int64_t)in[24] * qp[24];
    tmp3 = (int64_t)in[8] * qp[8];
    z1 = tmp0 + tmp3;
    z2 = tmp1 + tmp2;
    z3 = tmp0 + tmp2;
    z4 = tmp1 + tmp3;
    z5 = (z3 + z4) * FIX_1_175875602;
    tmp0 = tmp0 * FIX_0_298631336;
    tmp1 = tmp1 * FIX_2_053119869;
    tmp2 = tmp2 * FIX_3_072711026;
    tmp3 = tmp3 * FIX_1_501321110;
    z1 = z1 * (-FIX_0_899976223);
    z2 = z2 * (-FIX_2_562915447);
    z3 = z3 * (-FIX_1_961570560);
    z4 = z4 * (-FIX_0_390180644);
    z3 += z5;
    z4 += z5;
    tmp0 += z1 + z3;
    tmp1 += z2 + z4;
    tmp2 += z2 + z3;
    tmp3 += z1 + z4;

    wp[0] = (int)DESCALE(tmp10 + tmp3, CONST_BITS - PASS1_BITS);
    wp[56] = (int)DESCALE(tmp10 - tmp3, CONST_BITS - PASS1_BITS);
    wp[8] = (int)DESCALE(tmp11 + tmp2, CONST_BITS - PASS1_BITS);
    wp[48] = (int)DESCALE(tmp11 - tmp2, CONST_BITS - PASS1_BITS);
    wp[16] = (int)DESCALE(tmp12 + tmp1, CONST_BITS - PASS1_BITS);
    wp[40] = (int)DESCALE(tmp12 - tmp1, CONST_BITS - PASS1_BITS);
    wp[24] = (int)DESCALE(tmp13 + tmp0, CONST_BITS - PASS1_BITS);
    wp[32] = (int)DESCALE(tmp13 - tmp0, CONST_BITS - PASS1_BITS);
    in++; qp++; wp++;
  }

  wp = ws;
  for (ctr = 0; ctr < 8; ctr++) {
    uint8_t *o = out + ctr * stride;
    if (wp[1] == 0 && wp[2] == 0 && wp[3] == 0 && wp[4] == 0 &&
        wp[5] == 0 && wp[6] == 0 && wp[7] == 0) {
      uint8_t v = rl[(int)DESCALE((int64_t)wp[0], PASS1_BITS + 3) & 1023];
      o[0] = o[1] = o[2] = o[3] = o[4] = o[5] = o[6] = o[7] = v;
      wp += 8;
      continue;
    }
    z2 = wp[2];
    z3 = wp[6];
    z1 = (z2 + z3) * FIX_0_541196100;
    tmp2 = z1 + z3 * (-FIX_1_847759065);
    tmp3 = z1 + z2 * FIX_0_765366865;
    tmp0 = ((int64_t)wp[0] + (int64_t)wp[4]) * (1 << CONST_BITS);
    tmp1 = ((int64_t)wp[0] - (int64_t)wp[4]) * (1 << CONST_BITS);
    tmp10 = tmp0 + tmp3;
    tmp13 = tmp0 - tmp3;
    tmp11 = tmp1 + tmp2;
    tmp12 = tmp1 - tmp2;

    tmp0 = wp[7];
    tmp1 = wp[5];
    tmp2 = wp[3];
    tmp3 = wp[1];
    z1 = tmp0 + tmp3;
    z2 = tmp1 + tmp2;
    z3 = tmp0 + tmp2;
    z4 = tmp1 + tmp3;
    z5 = (z3 + z4) * FIX_1_175875602;
    tmp0 = tmp0 * FIX_0_298631336;
    tmp1 = tmp1 * FIX_2_053119869;
    tmp2 = tmp2 * FIX_3_072711026;
    tmp3 = tmp3 * FIX_1_501321110;
    z1 = z1 * (-FIX_0_899976223);
    z2 = z2 * (-FIX_2_562915447);
    z3 = z3 * (-FIX_1_961570560);
    z4 = z4 * (-FIX_0_390180644);
    z3 += z5;
    z4 += z5;
    tmp0 += z1 + z3;
    tmp1 += z2 + z4;
    tmp2 += z2 + z3;
    tmp3 += z1 + z4;

#define OUTB(x) rl[(int)DESCALE((x), CONST_BITS + PASS1_BITS + 3) & 1023]
    o[0] = OUTB(tmp10 + tmp3);
    o[7] = OUTB(tmp10 - tmp3);
    o[1] = OUTB(tmp11 + tmp2);
    o[6] = OUTB(tmp11 - tmp2);
    o[2] = OUTB(tmp12 + tmp1);
    o[5] = OUTB(tmp12 - tmp1);
    o[3] = OUTB(tmp13 + tmp0);
    o[4] = OUTB(tmp13 - tmp0);
#undef OUTB
    wp += 8;
  }
}

/* ------------------------------------------------------------------ */
/* setup                                                                */

static int div_round_up(long a, long b) { return (int)((a + b - 1) / b); }

static void initial_setup(jdec *d)
{
  int ci;
  if (d->height > 65500 || d->width > 65500)
    jd_error(d, "Maximum supported image dimension is %u pixels", 65500u);
  if (d->precision != 8)
    jd_error(d, "Unsupported JPEG data precision %d", d->precision);
  d->hmax = d->vmax = 1;
  for (ci = 0; ci < d->ncomp; ci++) {
    jd_comp *c = &d->comp[ci];
    if (c->h <= 0 || c->h > 4 || c->v <= 0 || c->v > 4)
      jd_error(d, "Bogus sampling factors");
    if (c->h > d->hmax) d->hmax = c->h;
    if (c->v > d->vmax) d->vmax = c->v;
  }
  d->mcus_x = div_round_up(d->width, d->hmax * 8);
  d->mcus_y = div_round_up(d->height, d->vmax * 8);
  d->total_imcu_rows = d->mcus_y;
  for (ci = 0; ci < d->ncomp; ci++) {
    jd_comp *c = &d->comp[ci];
    int k;
    c->bw = div_round_up((long)d->width * c->h, d->hmax * 8);
    c->bh = div_round_up((long)d->height * c->v, d->vmax * 8);
    c->dw = div_round_up((long)d->width * c->h, d->hmax);
    c->dh = div_round_up((long)d->height * c->v, d->vmax);
    c->stride = d->mcus_x * c->h * 8;
    c->plane = calloc((size_t)c->stride * (size_t)(d->mcus_y * c->v * 8), 1);
    if (!c->plane)
      jd_error(d, "Insufficient memory (case %d)", 4);
    c->coef = NULL;
    c->qt_latched = 0;
    for (k = 0; k < 64; k++)
      c->coef_bits[k] = -1;
  }
  if (d->scan_ncomp < d->ncomp || d->progressive)
    d->has_multiple_scans = 1;
  else
    d->has_multiple_scans = 0;
}

static void default_decompress_parms(jdec *d)
{
  switch (d->ncomp) {
  case 1:
    d->color_space = CS_GRAY;
    d->out_components = 1;
    break;
  case 3:
    if (d->saw_jfif) {
      d->color_space = CS_YCC;
    } else if (d->saw_adobe) {
      switch (d->adobe_transform) {
      case 0: d->color_space = CS_RGB; break;
      case 1: d->color_space = CS_YCC; break;
      default:
        jd_warn(d, "Unknown Adobe color transform code %d", d->adobe_transform);
        d->color_space = CS_YCC;
        break;
      }
    } else {
      int c0 = d->comp[0].id, c1 = d->comp[1].id, c2 = d->comp[2].id;
      if (c0 == 1 && c1 == 2 && c2 == 3)
        d->color_space = CS_YCC;
      else if (c0 == 82 && c1 == 71 && c2 == 66)
        d->color_space = CS_RGB;
      else
        d->color_space = CS_YCC;
    }
    d->out_components = 3;
    break;
  case 4:
    if (d->saw_adobe) {
      switch (d->adobe_transform) {
      case 0: d->color_space = CS_CMYK; break;
      case 2: d->color_space = CS_YCCK; break;
      default:
        jd_warn(d, "Unknown Adobe color transform code %d", d->adobe_transform);
        d->color_space = CS_YCCK;
        break;
      }
    } else {
      d->color_space = CS_CMYK;
    }
    d->out_components = 4;
    break;
  default:
    d->color_space = 0;
    d->out_components = d->ncomp;
    break;
  }
}

jdec *jd_create(FILE *in)
{
  jdec *d = calloc(1, sizeof(jdec));
  if (!d) {
    fprintf(stderr, "Insufficient memory (case %d)\n", 0);
    exit(1);
  }
  d->in = in;
  d->start_of_file = 1;
  saw_soi = 0;
  if (!sample_range_limit)
    prepare_range_limit();
  return d;
}

void jd_read_header(jdec *d)
{
  int r = read_markers(d);
  if (r == 2) {
    if (d->saw_sof)
      jd_error(d, "Invalid JPEG file structure: missing SOS marker");
    jd_error(d, "JPEG datastream contains no image");
  }
  initial_setup(d);
  default_decompress_parms(d);
}

/* ------------------------------------------------------------------ */
/* scan decoding                                                        */

static void latch_quant(jdec *d)
{
  int i;
  for (i = 0; i < d->scan_ncomp; i++) {
    jd_comp *c = &d->comp[d->scan_comp[i]];
    if (c->qt_latched)
      continue;
    if (c->tq < 0 || c->tq >= 4 || !d->qtab_defined[c->tq])
      jd_error(d, "Quantization table 0x%02x was not defined", c->tq);
    memcpy(c->qt, d->qtab[c->tq], sizeof(c->qt));
    c->qt_latched = 1;
  }
}

static int16_t *coef_block(jd_comp *c, int bx, int by)
{
  return c->coef + ((size_t)by * (size_t)(c->stride / 8) + (size_t)bx) * 64;
}

/* per-scan state */
static int scan_mcus_x, scan_mcus_y;
static int scan_mcu_row;

static void start_scan(jdec *d)
{
  int i;
  latch_quant(d);
  if (d->scan_ncomp == 1) {
    jd_comp *c = &d->comp[d->scan_comp[0]];
    scan_mcus_x = c->bw;
    scan_mcus_y = c->bh;
  } else {
    int blocks = 0;
    scan_mcus_x = d->mcus_x;
    scan_mcus_y = d->mcus_y;
    for (i = 0; i < d->scan_ncomp; i++) {
      jd_comp *c = &d->comp[d->scan_comp[i]];
      blocks += c->h * c->v;
    }
    if (blocks > 10)
      jd_error(d, "Sampling factors too large for interleaved scan");
  }
  if (d->progressive) {
    int bad = 0;
    int is_dc = (d->Ss == 0);
    if (is_dc) {
      if (d->Se != 0) bad = 1;
    } else {
      if (d->Ss > d->Se || d->Se >= 64) bad = 1;
      if (d->scan_ncomp != 1) bad = 1;
    }
    if (d->Ah != 0) {
      if (d->Al != d->Ah - 1) bad = 1;
    }
    if (d->Al > 13) bad = 1;
    if (bad)
      jd_error(d, "Invalid progressive parameters Ss=%d Se=%d Ah=%d Al=%d",
               d->Ss, d->Se, d->Ah, d->Al);
    for (i = 0; i < d->scan_ncomp; i++) {
      int ci = d->scan_comp[i];
      int *cb = d->comp[ci].coef_bits;
      int k;
      if (!is_dc && cb[0] < 0)
        jd_warn(d, "Inconsistent progression sequence for component %d coefficient %d", ci, 0);
      for (k = d->Ss; k <= d->Se; k++) {
        int expected = (cb[k] < 0) ? 0 : cb[k];
        if (d->Ah != expected)
          jd_warn(d, "Inconsistent progression sequence for component %d coefficient %d", ci, k);
        cb[k] = d->Al;
      }
    }
    for (i = 0; i < d->scan_ncomp; i++) {
      jd_comp *c = &d->comp[d->scan_comp[i]];
      if (is_dc) {
        if (d->Ah == 0) {
          if (!d->dc_tab[c->td].defined)
            jd_error(d, "Huffman table 0x%02x was not defined", c->td);
          make_derived(d, &d->dc_tab[c->td], 1);
        }
      } else {
        if (!d->ac_tab[c->ta].defined)
          jd_error(d, "Huffman table 0x%02x was not defined", c->ta);
        make_derived(d, &d->ac_tab[c->ta], 0);
      }
      c->last_dc = 0;
      c->eobrun = 0;
    }
  } else {
    if (d->arith)
      jd_error(d, "Unsupported JPEG process: SOF type 0x%02x", 0xc9);
    if (d->Ss != 0 || d->Se != 63 || d->Ah != 0 || d->Al != 0)
      jd_warn(d, "Invalid SOS parameters for sequential JPEG");
    for (i = 0; i < d->scan_ncomp; i++) {
      jd_comp *c = &d->comp[d->scan_comp[i]];
      if (!d->dc_tab[c->td].defined)
        jd_error(d, "Huffman table 0x%02x was not defined", c->td);
      make_derived(d, &d->dc_tab[c->td], 1);
      if (!d->ac_tab[c->ta].defined)
        jd_error(d, "Huffman table 0x%02x was not defined", c->ta);
      make_derived(d, &d->ac_tab[c->ta], 0);
      c->last_dc = 0;
    }
  }
  d->bits_left = 0;
  gbuf = 0;
  d->insufficient = 0;
  d->restarts_to_go = d->restart_interval;
  scan_mcu_row = 0;
}

/* decode one block, sequential mode */
static void decode_block_seq(jdec *d, jd_comp *c, int16_t *blk)
{
  int s, k, r;
  jd_huff *dc = &d->dc_tab[c->td];
  jd_huff *ac = &d->ac_tab[c->ta];
  s = huff_decode(d, dc);
  if (s) {
    r = get_bits(d, s);
    s = huff_extend(r, s);
  }
  s += c->last_dc;
  c->last_dc = s;
  blk[0] = (int16_t)s;
  for (k = 1; k < 64; k++) {
    s = huff_decode(d, ac);
    r = s >> 4;
    s &= 15;
    if (s) {
      k += r;
      r = get_bits(d, s);
      s = huff_extend(r, s);
      blk[natural_order[k]] = (int16_t)s;
    } else {
      if (r != 15)
        break;
      k += 15;
    }
  }
}

static void decode_dc_first(jdec *d, jd_comp *c, int16_t *blk)
{
  int s, r;
  s = huff_decode(d, &d->dc_tab[c->td]);
  if (s) {
    r = get_bits(d, s);
    s = huff_extend(r, s);
  }
  s += c->last_dc;
  c->last_dc = s;
  blk[0] = (int16_t)(int)((unsigned)s << d->Al);
}

static void decode_dc_refine(jdec *d, int16_t *blk)
{
  int p1 = 1 << d->Al;
  if (get_bits(d, 1))
    blk[0] = (int16_t)(blk[0] | p1);
}

static void decode_ac_first(jdec *d, jd_comp *c, int16_t *blk)
{
  int s, k, r;
  int Se = d->Se, Al = d->Al;
  jd_huff *ac = &d->ac_tab[c->ta];
  if (c->eobrun > 0) {
    c->eobrun--;
    return;
  }
  for (k = d->Ss; k <= Se; k++) {
    s = huff_decode(d, ac);
    r = s >> 4;
    s &= 15;
    if (s) {
      k += r;
      r = get_bits(d, s);
      s = huff_extend(r, s);
      blk[natural_order[k]] = (int16_t)(int)((unsigned)s << Al);
    } else {
      if (r == 15) {
        k += 15;
      } else {
        int eob = 1 << r;
        if (r)
          eob += get_bits(d, r);
        c->eobrun = eob - 1;
        break;
      }
    }
  }
}

static void decode_ac_refine(jdec *d, jd_comp *c, int16_t *blk)
{
  int Se = d->Se;
  int p1 = 1 << d->Al;
  int m1 = (int)((unsigned)-1 << d->Al);
  int s, k, r;
  int eobrun = c->eobrun;
  jd_huff *ac = &d->ac_tab[c->ta];
  k = d->Ss;
  if (eobrun == 0) {
    for (; k <= Se; k++) {
      s = huff_decode(d, ac);
      r = s >> 4;
      s &= 15;
      if (s) {
        if (s != 1)
          jd_warn(d, "Corrupt JPEG data: bad Huffman code");
        if (get_bits(d, 1))
          s = p1;
        else
          s = m1;
      } else {
        if (r != 15) {
          eobrun = 1 << r;
          if (r)
            eobrun += get_bits(d, r);
          break;
        }
      }
      do {
        int16_t *t = blk + natural_order[k];
        if (*t != 0) {
          if (get_bits(d, 1)) {
            if ((*t & p1) == 0) {
              if (*t >= 0)
                *t = (int16_t)(*t + p1);
              else
                *t = (int16_t)(*t + m1);
            }
          }
        } else {
          if (--r < 0)
            break;
        }
        k++;
      } while (k <= Se);
      if (s) {
        int pos = natural_order[k];
        blk[pos] = (int16_t)s;
      }
    }
  }
  if (eobrun > 0) {
    for (; k <= Se; k++) {
      int16_t *t = blk + natural_order[k];
      if (*t != 0) {
        if (get_bits(d, 1)) {
          if ((*t & p1) == 0) {
            if (*t >= 0)
              *t = (int16_t)(*t + p1);
            else
              *t = (int16_t)(*t + m1);
          }
        }
      }
    }
    eobrun--;
  }
  c->eobrun = eobrun;
}

static void decode_block_any(jdec *d, jd_comp *c, int16_t *blk)
{
  if (!d->progressive) {
    decode_block_seq(d, c, blk);
  } else if (d->Ss == 0) {
    if (d->Ah == 0)
      decode_dc_first(d, c, blk);
    else
      decode_dc_refine(d, blk);
  } else {
    if (d->Ah == 0)
      decode_ac_first(d, c, blk);
    else
      decode_ac_refine(d, c, blk);
  }
}

/* Decode one MCU row of the current scan into coefficient buffers
 * (if tobuf) or directly into sample planes. */
static void decode_mcu_row(jdec *d, int tobuf)
{
  int mx, i, bx, by;
  int16_t tmp[64];
  int my = scan_mcu_row;
  for (mx = 0; mx < scan_mcus_x; mx++) {
    if (d->restart_interval) {
      if (d->restarts_to_go == 0)
        process_restart(d);
    }
    if (d->scan_ncomp == 1) {
      jd_comp *c = &d->comp[d->scan_comp[0]];
      int16_t *blk = tobuf ? coef_block(c, mx, my) : tmp;
      if (!tobuf)
        memset(tmp, 0, sizeof(tmp));
      if (!d->insufficient || (d->progressive && d->Ss == 0 && d->Ah != 0))
        decode_block_any(d, c, blk);
      if (!tobuf)
        idct_islow(tmp, c->qt, c->plane + (size_t)my * 8 * c->stride + (size_t)mx * 8, c->stride);
    } else {
      int skip = d->insufficient && !(d->progressive && d->Ss == 0 && d->Ah != 0);
      for (i = 0; i < d->scan_ncomp; i++) {
        jd_comp *c = &d->comp[d->scan_comp[i]];
        for (by = 0; by < c->v; by++) {
          for (bx = 0; bx < c->h; bx++) {
            int gx = mx * c->h + bx, gy = my * c->v + by;
            int16_t *blk = tobuf ? coef_block(c, gx, gy) : tmp;
            if (!tobuf)
              memset(tmp, 0, sizeof(tmp));
            if (!skip)
              decode_block_any(d, c, blk);
            if (!tobuf && gx < c->bw && gy < c->bh)
              idct_islow(tmp, c->qt, c->plane + (size_t)gy * 8 * c->stride + (size_t)gx * 8, c->stride);
          }
        }
      }
    }
    if (d->restart_interval)
      d->restarts_to_go--;
  }
  scan_mcu_row++;
}

static void finish_scan_input(jdec *d)
{
  (void)d;
}

void jd_start_decompress(jdec *d)
{
  int ci;
  d->output_scanline = 0;
  for (ci = 0; ci < d->ncomp; ci++) {
    d->rowbuf[ci] = calloc((size_t)d->comp[ci].stride * (size_t)d->hmax + 16, 1);
  }
  if (d->has_multiple_scans) {
    int r;
    for (ci = 0; ci < d->ncomp; ci++) {
      jd_comp *c = &d->comp[ci];
      size_t nb = (size_t)(c->stride / 8) * (size_t)(d->mcus_y * c->v);
      c->coef = calloc(nb * 64, sizeof(int16_t));
      if (!c->coef)
        jd_error(d, "Insufficient memory (case %d)", 4);
    }
    /* absorb the whole file */
    for (;;) {
      start_scan(d);
      while (scan_mcu_row < scan_mcus_y)
        decode_mcu_row(d, 1);
      finish_scan_input(d);
      r = read_markers(d);
      if (r == 2)
        break;
    }
    d->eoi_reached = 1;
    for (ci = 0; ci < d->ncomp; ci++) {
      jd_comp *c = &d->comp[ci];
      int bx, by;
      if (!c->qt_latched) {
        /* component never appeared in a scan */
        if (c->tq >= 0 && c->tq < 4 && d->qtab_defined[c->tq]) {
          memcpy(c->qt, d->qtab[c->tq], sizeof(c->qt));
        } else {
          jd_error(d, "Quantization table 0x%02x was not defined", c->tq);
        }
      }
      for (by = 0; by < c->bh; by++)
        for (bx = 0; bx < c->bw; bx++)
          idct_islow(coef_block(c, bx, by), c->qt,
                     c->plane + (size_t)by * 8 * c->stride + (size_t)bx * 8, c->stride);
    }
    d->imcu_rows_decoded = d->total_imcu_rows;
  } else {
    start_scan(d);
    d->imcu_rows_decoded = 0;
  }
}

static void ensure_imcu(jdec *d, int row)
{
  if (row >= d->total_imcu_rows)
    row = d->total_imcu_rows - 1;
  while (d->imcu_rows_decoded <= row) {
    decode_mcu_row(d, 0);
    d->imcu_rows_decoded++;
  }
}

/* ------------------------------------------------------------------ */
/* upsampling and color conversion                                     */

static const uint8_t *comp_row(jd_comp *c, int y)
{
  if (y < 0) y = 0;
  if (y >= c->dh) y = c->dh - 1;
  return c->plane + (size_t)y * c->stride;
}

static void upsample_row(jdec *d, int ci, int y, uint8_t *out)
{
  jd_comp *c = &d->comp[ci];
  int hexp = d->hmax / c->h;
  int vexp = d->vmax / c->v;
  int dw = c->dw;
  int x;
  if (c->h == d->hmax && c->v == d->vmax) {
    memcpy(out, comp_row(c, y), (size_t)dw);
    return;
  }
  if (hexp * c->h != d->hmax || vexp * c->v != d->vmax)
    jd_error(d, "Fractional sampling not implemented yet");
  if (hexp == 2 && vexp == 1) {
    const uint8_t *in = comp_row(c, y);
    if (dw > 2) {
      int v;
      v = in[0];
      out[0] = (uint8_t)v;
      out[1] = (uint8_t)((v * 3 + in[1] + 2) >> 2);
      for (x = 1; x < dw - 1; x++) {
        v = in[x] * 3;
        out[2 * x] = (uint8_t)((v + in[x - 1] + 1) >> 2);
        out[2 * x + 1] = (uint8_t)((v + in[x + 1] + 2) >> 2);
      }
      v = in[dw - 1];
      out[2 * (dw - 1)] = (uint8_t)((v * 3 + in[dw - 2] + 1) >> 2);
      out[2 * (dw - 1) + 1] = (uint8_t)v;
    } else {
      for (x = 0; x < dw; x++)
        out[2 * x] = out[2 * x + 1] = in[x];
    }
    return;
  }
  if (hexp == 2 && vexp == 2) {
    int sy = y / 2;
    if (dw > 2) {
      const uint8_t *in0 = comp_row(c, sy);
      const uint8_t *in1 = comp_row(c, (y & 1) ? sy + 1 : sy - 1);
      int thiscol, lastcol, nextcol;
      thiscol = in0[0] * 3 + in1[0];
      nextcol = in0[1] * 3 + in1[1];
      out[0] = (uint8_t)((thiscol * 4 + 8) >> 4);
      out[1] = (uint8_t)((thiscol * 3 + nextcol + 7) >> 4);
      lastcol = thiscol;
      thiscol = nextcol;
      for (x = 1; x < dw - 1; x++) {
        nextcol = in0[x + 1] * 3 + in1[x + 1];
        out[2 * x] = (uint8_t)((thiscol * 3 + lastcol + 8) >> 4);
        out[2 * x + 1] = (uint8_t)((thiscol * 3 + nextcol + 7) >> 4);
        lastcol = thiscol;
        thiscol = nextcol;
      }
      out[2 * (dw - 1)] = (uint8_t)((thiscol * 3 + lastcol + 8) >> 4);
      out[2 * (dw - 1) + 1] = (uint8_t)((thiscol * 4 + 7) >> 4);
    } else {
      const uint8_t *in = comp_row(c, sy);
      for (x = 0; x < dw; x++)
        out[2 * x] = out[2 * x + 1] = in[x];
    }
    return;
  }
  if (hexp == 1 && vexp == 2) {
    int sy = y / 2;
    const uint8_t *in0 = comp_row(c, sy);
    const uint8_t *in1;
    int bias;
    if (y & 1) {
      in1 = comp_row(c, sy + 1);
      bias = 2;
    } else {
      in1 = comp_row(c, sy - 1);
      bias = 1;
    }
    for (x = 0; x < dw; x++)
      out[x] = (uint8_t)((in0[x] * 3 + in1[x] + bias) >> 2);
    return;
  }
  /* generic integral upsampling: replicate */
  {
    const uint8_t *in = comp_row(c, y / vexp);
    int k;
    for (x = 0; x < dw; x++)
      for (k = 0; k < hexp; k++)
        out[x * hexp + k] = in[x];
  }
}

static int ycc_tabs_ready;
static int Cr_r_tab[256], Cb_b_tab[256];
static int32_t Cr_g_tab[256], Cb_g_tab[256];

static void build_ycc_tables(void)
{
  int i;
  const int SCALEBITS = 16;
  const int32_t ONE_HALF = (int32_t)1 << (SCALEBITS - 1);
#define FIXK(x) ((int32_t)((x) * (1L << SCALEBITS) + 0.5))
  for (i = 0; i < 256; i++) {
    int32_t x = i - 128;
    Cr_r_tab[i] = (int)((FIXK(1.40200) * x + ONE_HALF) >> SCALEBITS);
    Cb_b_tab[i] = (int)((FIXK(1.77200) * x + ONE_HALF) >> SCALEBITS);
    Cr_g_tab[i] = (-FIXK(0.71414)) * x;
    Cb_g_tab[i] = (-FIXK(0.34414)) * x + ONE_HALF;
  }
#undef FIXK
  ycc_tabs_ready = 1;
}

/* return the image row index of the last iMCU row needed for output row y */
static int needed_imcu(jdec *d, int y)
{
  int ci;
  int need = y / (d->vmax * 8);
  for (ci = 0; ci < d->ncomp; ci++) {
    jd_comp *c = &d->comp[ci];
    int vexp = d->vmax / c->v;
    if (vexp == 2 && (c->h == d->hmax || (d->hmax / c->h == 2 && c->dw > 2) || d->hmax / c->h == 1)) {
      /* context rows needed: next component row */
      int sy = y / 2 + 1;
      int r;
      if (sy >= c->dh) sy = c->dh - 1;
      r = sy / (c->v * 8);
      if (r > need) need = r;
    }
  }
  return need;
}

void jd_read_scanline(jdec *d, uint8_t *out)
{
  int y = d->output_scanline;
  int ci, x, W = d->width;
  if (y >= d->height)
    return;
  if (!d->has_multiple_scans)
    ensure_imcu(d, needed_imcu(d, y));
  for (ci = 0; ci < d->ncomp; ci++)
    upsample_row(d, ci, y, d->rowbuf[ci]);
  switch (d->color_space) {
  case CS_GRAY:
    memcpy(out, d->rowbuf[0], (size_t)W);
    break;
  case CS_YCC: {
    const uint8_t *Y = d->rowbuf[0], *Cb = d->rowbuf[1], *Cr = d->rowbuf[2];
    if (!ycc_tabs_ready)
      build_ycc_tables();
    for (x = 0; x < W; x++) {
      int yy = Y[x], cb = Cb[x], cr = Cr[x];
      out[3 * x] = sample_range_limit[yy + Cr_r_tab[cr]];
      out[3 * x + 1] = sample_range_limit[yy + (int)((Cb_g_tab[cb] + Cr_g_tab[cr]) >> 16)];
      out[3 * x + 2] = sample_range_limit[yy + Cb_b_tab[cb]];
    }
    break;
  }
  case CS_RGB:
    for (x = 0; x < W; x++) {
      out[3 * x] = d->rowbuf[0][x];
      out[3 * x + 1] = d->rowbuf[1][x];
      out[3 * x + 2] = d->rowbuf[2][x];
    }
    break;
  case CS_CMYK:
    for (x = 0; x < W; x++) {
      out[4 * x] = d->rowbuf[0][x];
      out[4 * x + 1] = d->rowbuf[1][x];
      out[4 * x + 2] = d->rowbuf[2][x];
      out[4 * x + 3] = d->rowbuf[3][x];
    }
    break;
  case CS_YCCK: {
    if (!ycc_tabs_ready)
      build_ycc_tables();
    for (x = 0; x < W; x++) {
      int yy = d->rowbuf[0][x], cb = d->rowbuf[1][x], cr = d->rowbuf[2][x];
      out[4 * x] = sample_range_limit[255 - (yy + Cr_r_tab[cr])];
      out[4 * x + 1] = sample_range_limit[255 - (yy + (int)((Cb_g_tab[cb] + Cr_g_tab[cr]) >> 16))];
      out[4 * x + 2] = sample_range_limit[255 - (yy + Cb_b_tab[cb])];
      out[4 * x + 3] = d->rowbuf[3][x];
    }
    break;
  }
  default:
    for (x = 0; x < W; x++)
      for (ci = 0; ci < d->ncomp; ci++)
        out[d->ncomp * x + ci] = d->rowbuf[ci][x];
    break;
  }
  d->output_scanline++;
}

void jd_finish_decompress(jdec *d)
{
  if (d->eoi_reached)
    return;
  /* read until EOI */
  for (;;) {
    int r = read_markers(d);
    if (r == 2)
      break;
    if (!d->has_multiple_scans)
      jd_error(d, "Bogus JPEG library state");
  }
  d->eoi_reached = 1;
}

void jd_destroy(jdec *d)
{
  int ci;
  for (ci = 0; ci < JD_MAXCOMP; ci++) {
    free(d->comp[ci].plane);
    free(d->comp[ci].coef);
    free(d->rowbuf[ci]);
  }
  free(d);
}
EOF
echo done"}

actions.command:
cat > /workspace/src/jdec.c <<'EOF'
/*
 * Small baseline/progressive JPEG decoder.
 *
 * The goal of this decoder is to produce exactly the same samples as the
 * default configuration of the common IJG-derived decoders: accurate
 * integer IDCT, "fancy" (triangle filter) chroma upsampling and fixed point
 * YCbCr->RGB conversion.  Error and warning messages follow the wording of
 * those libraries, as they are visible to the user.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "jdec.h"

#define M_SOF0 0xc0
#define M_SOF1 0xc1
#define M_SOF2 0xc2
#define M_SOF3 0xc3
#define M_DHT 0xc4
#define M_SOF5 0xc5
#define M_SOF6 0xc6
#define M_SOF7 0xc7
#define M_JPG 0xc8
#define M_SOF9 0xc9
#define M_SOF10 0xca
#define M_SOF11 0xcb
#define M_DAC 0xcc
#define M_SOF13 0xcd
#define M_SOF14 0xce
#define M_SOF15 0xcf
#define M_RST0 0xd0
#define M_RST7 0xd7
#define M_SOI 0xd8
#define M_EOI 0xd9
#define M_SOS 0xda
#define M_DQT 0xdb
#define M_DNL 0xdc
#define M_DRI 0xdd
#define M_APP0 0xe0
#define M_APP14 0xee
#define M_APP15 0xef
#define M_COM 0xfe
#define M_TEM 0x01

#define CS_GRAY 1
#define CS_RGB 2
#define CS_YCC 3
#define CS_CMYK 4
#define CS_YCCK 5

static const int natural_order[64 + 16] = {
  0,  1,  8, 16,  9,  2,  3, 10,
 17, 24, 32, 25, 18, 11,  4,  5,
 12, 19, 26, 33, 40, 48, 41, 34,
 27, 20, 13,  6,  7, 14, 21, 28,
 35, 42, 49, 56, 57, 50, 43, 36,
 29, 22, 15, 23, 30, 37, 44, 51,
 58, 59, 52, 45, 38, 31, 39, 46,
 53, 60, 61, 54, 47, 55, 62, 63,
 63, 63, 63, 63, 63, 63, 63, 63,
 63, 63, 63, 63, 63, 63, 63, 63
};

/* ------------------------------------------------------------------ */
/* messages                                                             */

static void jd_error(jdec *d, const char *fmt, ...)
  __attribute__((noreturn, format(printf, 2, 3)));

#include <stdarg.h>
static void jd_error(jdec *d, const char *fmt, ...)
{
  va_list ap;
  (void)d;
  va_start(ap, fmt);
  vfprintf(stderr, fmt, ap);
  va_end(ap);
  fputc('\n', stderr);
  exit(1);
}

static void jd_warn(jdec *d, const char *fmt, ...)
  __attribute__((format(printf, 2, 3)));

static void jd_warn(jdec *d, const char *fmt, ...)
{
  va_list ap;
  if (d->num_warnings == 0) {
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    va_end(ap);
    fputc('\n', stderr);
  }
  d->num_warnings++;
}

/* ------------------------------------------------------------------ */
/* input source (stdio, 4096 byte buffer, fake EOI on premature EOF)    */

static void fill_input(jdec *d)
{
  size_t n = fread(d->buf, 1, sizeof(d->buf), d->in);
  if (n == 0) {
    if (d->start_of_file)
      jd_error(d, "Empty input file");
    jd_warn(d, "Premature end of JPEG file");
    d->buf[0] = 0xFF;
    d->buf[1] = M_EOI;
    n = 2;
  }
  d->pos = 0;
  d->len = n;
  d->start_of_file = 0;
}

static int read_byte(jdec *d)
{
  if (d->pos >= d->len)
    fill_input(d);
  return d->buf[d->pos++];
}

static unsigned read_2bytes(jdec *d)
{
  unsigned a = (unsigned)read_byte(d);
  unsigned b = (unsigned)read_byte(d);
  return (a << 8) | b;
}

static void skip_input(jdec *d, long n)
{
  if (n <= 0)
    return;
  while (n > (long)(d->len - d->pos)) {
    n -= (long)(d->len - d->pos);
    d->pos = d->len;
    fill_input(d);
  }
  d->pos += (size_t)n;
}

/* ------------------------------------------------------------------ */
/* markers                                                              */

static void first_marker(jdec *d)
{
  int c = read_byte(d);
  int c2 = read_byte(d);
  if (c != 0xFF || c2 != M_SOI)
    jd_error(d, "Not a JPEG file: starts with 0x%02x 0x%02x", c, c2);
  d->unread_marker = c2;
}

static void next_marker(jdec *d)
{
  int c;
  for (;;) {
    c = read_byte(d);
    while (c != 0xFF) {
      d->discarded_bytes++;
      c = read_byte(d);
    }
    do {
      c = read_byte(d);
    } while (c == 0xFF);
    if (c != 0)
      break;
    d->discarded_bytes += 2;
  }
  if (d->discarded_bytes != 0) {
    jd_warn(d, "Corrupt JPEG data: %u extraneous bytes before marker 0x%02x",
            d->discarded_bytes, c);
    d->discarded_bytes = 0;
  }
  d->unread_marker = c;
}

static int saw_soi;

static void get_soi(jdec *d)
{
  if (saw_soi)
    jd_error(d, "Invalid JPEG file structure: two SOI markers");
  d->restart_interval = 0;
  d->saw_jfif = 0;
  d->saw_adobe = 0;
  d->adobe_transform = 0;
  saw_soi = 1;
}

static void get_sof(jdec *d, int prog, int arith)
{
  unsigned length;
  int i;
  d->progressive = prog;
  d->arith = arith;
  length = read_2bytes(d);
  d->precision = read_byte(d);
  d->height = (int)read_2bytes(d);
  d->width = (int)read_2bytes(d);
  d->ncomp = read_byte(d);
  length -= 8;
  if (d->saw_sof)
    jd_error(d, "Invalid JPEG file structure: two SOF markers");
  if (d->height <= 0 || d->width <= 0 || d->ncomp <= 0)
    jd_error(d, "Empty JPEG image (DNL not supported)");
  if (length != (unsigned)(d->ncomp * 3))
    jd_error(d, "Bogus marker length");
  if (d->ncomp > JD_MAXCOMP)
    jd_error(d, "Too many color components: %d, max %d", d->ncomp, 10);
  for (i = 0; i < d->ncomp; i++) {
    int c;
    d->comp[i].id = read_byte(d);
    c = read_byte(d);
    d->comp[i].h = (c >> 4) & 15;
    d->comp[i].v = c & 15;
    d->comp[i].tq = read_byte(d);
  }
  d->saw_sof = 1;
}

static void get_sos(jdec *d)
{
  unsigned length;
  int n, i, c;
  if (!d->saw_sof)
    jd_error(d, "Invalid JPEG file structure: SOS before SOF");
  length = read_2bytes(d);
  n = read_byte(d);
  if (length != (unsigned)(n * 2 + 6) || n < 1 || n > 4)
    jd_error(d, "Bogus marker length");
  d->scan_ncomp = n;
  for (i = 0; i < n; i++) {
    int cc = read_byte(d);
    int ci, pi;
    c = read_byte(d);
    for (ci = 0; ci < d->ncomp; ci++) {
      if (cc == d->comp[ci].id)
        break;
    }
    if (ci >= d->ncomp)
      jd_error(d, "Invalid component ID %d in SOS", cc);
    for (pi = 0; pi < i; pi++)
      if (d->scan_comp[pi] == ci)
        jd_error(d, "Invalid component ID %d in SOS", cc);
    d->scan_comp[i] = ci;
    d->comp[ci].td = (c >> 4) & 15;
    d->comp[ci].ta = c & 15;
  }
  d->Ss = read_byte(d);
  d->Se = read_byte(d);
  c = read_byte(d);
  d->Ah = (c >> 4) & 15;
  d->Al = c & 15;
  d->next_restart_num = 0;
}

static void get_dht(jdec *d)
{
  long length = (long)read_2bytes(d) - 2;
  while (length > 16) {
    int index = read_byte(d);
    uint8_t bits[17];
    uint8_t vals[256];
    int count = 0, i;
    jd_huff *h;
    bits[0] = 0;
    for (i = 1; i <= 16; i++) {
      bits[i] = (uint8_t)read_byte(d);
      count += bits[i];
    }
    length -= 1 + 16;
    if (count > 256 || (long)count > length)
      jd_error(d, "Bogus Huffman table definition");
    for (i = 0; i < count; i++)
      vals[i] = (uint8_t)read_byte(d);
    memset(&vals[count], 0, (size_t)(256 - count));
    length -= count;
    if (index & 0x10) {
      index -= 0x10;
      if (index < 0 || index >= 4)
        jd_error(d, "Bogus DHT index %d", index);
      h = &d->ac_tab[index];
    } else {
      if (index < 0 || index >= 4)
        jd_error(d, "Bogus DHT index %d", index);
      h = &d->dc_tab[index];
    }
    memcpy(h->bits, bits, sizeof(bits));
    memcpy(h->vals, vals, sizeof(vals));
    h->defined = 1;
  }
  if (length != 0)
    jd_error(d, "Bogus marker length");
}

static void get_dqt(jdec *d)
{
  long length = (long)read_2bytes(d) - 2;
  while (length > 0) {
    int n = read_byte(d);
    int prec = n >> 4;
    int i;
    n &= 0x0F;
    if (n >= 4)
      jd_error(d, "Bogus DQT index %d", n);
    for (i = 0; i < 64; i++) {
      unsigned tmp;
      if (prec)
        tmp = read_2bytes(d);
      else
        tmp = (unsigned)read_byte(d);
      d->qtab[n][natural_order[i]] = (uint16_t)tmp;
    }
    d->qtab_defined[n] = 1;
    length -= 64 + 1;
    if (prec)
      length -= 64;
  }
  if (length != 0)
    jd_error(d, "Bogus marker length");
}

static void get_dri(jdec *d)
{
  unsigned length = read_2bytes(d);
  if (length != 4)
    jd_error(d, "Bogus marker length");
  d->restart_interval = (int)read_2bytes(d);
}

static void get_interesting_appn(jdec *d, int marker)
{
  long length = (long)read_2bytes(d) - 2;
  uint8_t b[14];
  unsigned numtoread, i;
  if (length >= 14)
    numtoread = 14;
  else if (length > 0)
    numtoread = (unsigned)length;
  else
    numtoread = 0;
  for (i = 0; i < numtoread; i++)
    b[i] = (uint8_t)read_byte(d);
  length -= numtoread;
  if (marker == M_APP0) {
    if (numtoread >= 14 && b[0] == 0x4A && b[1] == 0x46 && b[2] == 0x49 &&
        b[3] == 0x46 && b[4] == 0) {
      d->saw_jfif = 1;
      if (b[5] != 1)
        jd_warn(d, "Warning: unknown JFIF revision number %d.%02d", b[5], b[6]);
    }
  } else {
    if (numtoread >= 12 && b[0] == 0x41 && b[1] == 0x64 && b[2] == 0x6F &&
        b[3] == 0x62 && b[4] == 0x65) {
      d->saw_adobe = 1;
      d->adobe_transform = b[11];
    }
  }
  if (length > 0)
    skip_input(d, length);
}

static void skip_variable(jdec *d)
{
  long length = (long)read_2bytes(d) - 2;
  if (length > 0)
    skip_input(d, length);
}

/* returns 1 when SOS reached, 2 when EOI reached */
static int read_markers(jdec *d)
{
  for (;;) {
    if (d->unread_marker == 0) {
      if (!saw_soi)
        first_marker(d);
      else
        next_marker(d);
    }
    switch (d->unread_marker) {
    case M_SOI:
      get_soi(d);
      break;
    case M_SOF0:
    case M_SOF1:
      get_sof(d, 0, 0);
      break;
    case M_SOF2:
      get_sof(d, 1, 0);
      break;
    case M_SOF9:
      get_sof(d, 0, 1);
      break;
    case M_SOF10:
      get_sof(d, 1, 1);
      break;
    case M_SOF3: case M_SOF5: case M_SOF6: case M_SOF7: case M_JPG:
    case M_SOF11: case M_SOF13: case M_SOF14: case M_SOF15:
      jd_error(d, "Unsupported JPEG process: SOF type 0x%02x", d->unread_marker);
    case M_SOS:
      get_sos(d);
      d->unread_marker = 0;
      return 1;
    case M_EOI:
      d->unread_marker = 0;
      return 2;
    case M_DAC:
      skip_variable(d);
      break;
    case M_DHT:
      get_dht(d);
      break;
    case M_DQT:
      get_dqt(d);
      break;
    case M_DRI:
      get_dri(d);
      break;
    case M_APP0:
    case M_APP14:
      get_interesting_appn(d, d->unread_marker);
      break;
    case 0xe1: case 0xe2: case 0xe3: case 0xe4: case 0xe5: case 0xe6:
    case 0xe7: case 0xe8: case 0xe9: case 0xea: case 0xeb: case 0xec:
    case 0xed: case 0xef: case M_COM:
      skip_variable(d);
      break;
    case 0xd0: case 0xd1: case 0xd2: case 0xd3: case 0xd4: case 0xd5:
    case 0xd6: case 0xd7: case M_TEM:
      break;
    case M_DNL:
      skip_variable(d);
      break;
    default:
      jd_error(d, "Unsupported marker type 0x%02x", d->unread_marker);
    }
    d->unread_marker = 0;
  }
}

/* ------------------------------------------------------------------ */
/* huffman decoding                                                     */

static void make_derived(jdec *d, jd_huff *h, int isdc)
{
  int huffsize[257];
  unsigned huffcode[257];
  int p, l, i, si, numsymbols;
  unsigned code;
  if (!h->defined)
    jd_error(d, "Huffman table 0x%02x was not defined", 0);
  p = 0;
  for (l = 1; l <= 16; l++) {
    i = h->bits[l];
    if (p + i > 256)
      jd_error(d, "Bogus Huffman table definition");
    while (i--)
      huffsize[p++] = l;
  }
  huffsize[p] = 0;
  numsymbols = p;
  code = 0;
  si = huffsize[0];
  p = 0;
  while (huffsize[p]) {
    while (huffsize[p] == si) {
      huffcode[p++] = code;
      code++;
    }
    if ((long)code >= (1L << si))
      jd_error(d, "Bogus Huffman table definition");
    code <<= 1;
    si++;
  }
  p = 0;
  for (l = 1; l <= 16; l++) {
    if (h->bits[l]) {
      h->valoffset[l] = (int32_t)p - (int32_t)huffcode[p];
      p += h->bits[l];
      h->maxcode[l] = (int32_t)huffcode[p - 1];
    } else {
      h->maxcode[l] = -1;
    }
  }
  h->valoffset[17] = 0;
  h->maxcode[17] = 0xFFFFF;
  if (isdc) {
    for (i = 0; i < numsymbols; i++) {
      if (h->vals[i] > 15)
        jd_error(d, "Bogus Huffman table definition");
    }
  }
}

#define BIT_BUF_SIZE 64
#define MIN_GET_BITS (BIT_BUF_SIZE - 7)

static uint64_t gbuf;

static void fill_bits(jdec *d, int nbits)
{
  if (d->unread_marker == 0) {
    while (d->bits_left < MIN_GET_BITS) {
      int c = read_byte(d);
      if (c == 0xFF) {
        do {
          c = read_byte(d);
        } while (c == 0xFF);
        if (c == 0) {
          c = 0xFF;
        } else {
          d->unread_marker = c;
          goto no_more;
        }
      }
      gbuf = (gbuf << 8) | (uint64_t)c;
      d->bits_left += 8;
    }
    return;
  }
no_more:
  if (nbits > d->bits_left) {
    if (!d->insufficient) {
      jd_warn(d, "Corrupt JPEG data: premature end of data segment");
      d->insufficient = 1;
    }
    gbuf <<= MIN_GET_BITS - d->bits_left;
    d->bits_left = MIN_GET_BITS;
  }
}

static inline int get_bits(jdec *d, int n)
{
  if (d->bits_left < n)
    fill_bits(d, n);
  d->bits_left -= n;
  return (int)((gbuf >> d->bits_left) & ((1u << n) - 1));
}

static int huff_decode(jdec *d, jd_huff *h)
{
  int l = 1;
  int32_t code = get_bits(d, 1);
  while (code > h->maxcode[l]) {
    code <<= 1;
    code |= get_bits(d, 1);
    l++;
  }
  if (l > 16) {
    jd_warn(d, "Corrupt JPEG data: bad Huffman code");
    return 0;
  }
  return h->vals[(int)(code + h->valoffset[l])];
}

static inline int huff_extend(int r, int s)
{
  return r < (1 << (s - 1)) ? r + (int)((unsigned)-1 << s) + 1 : r;
}

static void read_restart_marker(jdec *d);

static void process_restart(jdec *d)
{
  int ci;
  d->discarded_bytes += (unsigned)(d->bits_left / 8);
  d->bits_left = 0;
  read_restart_marker(d);
  for (ci = 0; ci < d->ncomp; ci++) {
    d->comp[ci].last_dc = 0;
    d->comp[ci].eobrun = 0;
  }
  d->restarts_to_go = d->restart_interval;
  if (d->unread_marker == 0)
    d->insufficient = 0;
}

static void resync_to_restart(jdec *d, int desired)
{
  int marker = d->unread_marker;
  int action;
  jd_warn(d, "Corrupt JPEG data: found marker 0x%02x instead of RST%d", marker, desired);
  for (;;) {
    if (marker < M_SOF0)
      action = 2;
    else if (marker < M_RST0 || marker > M_RST7)
      action = 3;
    else {
      if (marker == (M_RST0 + ((desired + 1) & 7)) ||
          marker == (M_RST0 + ((desired + 2) & 7)))
        action = 3;
      else if (marker == (M_RST0 + ((desired - 1) & 7)) ||
               marker == (M_RST0 + ((desired - 2) & 7)))
        action = 2;
      else
        action = 1;
    }
    switch (action) {
    case 1:
      d->unread_marker = 0;
      return;
    case 2:
      next_marker(d);
      marker = d->unread_marker;
      break;
    default:
      return;
    }
  }
}

static void read_restart_marker(jdec *d)
{
  if (d->unread_marker == 0)
    next_marker(d);
  if (d->unread_marker == M_RST0 + d->next_restart_num) {
    d->unread_marker = 0;
  } else {
    resync_to_restart(d, d->next_restart_num);
  }
  d->next_restart_num = (d->next_restart_num + 1) & 7;
}

/* ------------------------------------------------------------------ */
/* IDCT (accurate integer method)                                       */

#define CONST_BITS 13
#define PASS1_BITS 2
#define FIX_0_298631336 ((int64_t)2446)
#define FIX_0_390180644 ((int64_t)3196)
#define FIX_0_541196100 ((int64_t)4433)
#define FIX_0_765366865 ((int64_t)6270)
#define FIX_0_899976223 ((int64_t)7373)
#define FIX_1_175875602 ((int64_t)9633)
#define FIX_1_501321110 ((int64_t)12299)
#define FIX_1_847759065 ((int64_t)15137)
#define FIX_1_961570560 ((int64_t)16069)
#define FIX_2_053119869 ((int64_t)16819)
#define FIX_2_562915447 ((int64_t)20995)
#define FIX_3_072711026 ((int64_t)25172)
#define DESCALE(x, n) (((x) + ((int64_t)1 << ((n)-1))) >> (n))

static uint8_t range_table[5 * 256 + 128];
static uint8_t *sample_range_limit; /* limit[x] for x in -256..511 */
static uint8_t *idct_limit;

static void prepare_range_limit(void)
{
  uint8_t *table = range_table;
  int i;
  table += 256;
  sample_range_limit = table;
  memset(table - 256, 0, 256);
  for (i = 0; i <= 255; i++)
    table[i] = (uint8_t)i;
  table += 128;
  for (i = 128; i < 512; i++)
    table[i] = 255;
  memset(table + 512, 0, 512 - 128);
  memcpy(table + 1024 - 128, sample_range_limit, 128);
  idct_limit = sample_range_limit + 128;
}

static void idct_islow(const int16_t *coef, const uint16_t *q, uint8_t *out, int stride)
{
  int64_t tmp0, tmp1, tmp2, tmp3, tmp10, tmp11, tmp12, tmp13;
  int64_t z1, z2, z3, z4, z5;
  int ws[64];
  int ctr;
  const int16_t *in = coef;
  const uint16_t *qp = q;
  int *wp = ws;
  uint8_t *rl = idct_limit;

  for (ctr = 8; ctr > 0; ctr--) {
    if (in[8] == 0 && in[16] == 0 && in[24] == 0 && in[32] == 0 &&
        in[40] == 0 && in[48] == 0 && in[56] == 0) {
      int dcval = (int)(((int)in[0] * (int)qp[0]) * (1 << PASS1_BITS));
      wp[0] = wp[8] = wp[16] = wp[24] = wp[32] = wp[40] = wp[48] = wp[56] = dcval;
      in++; qp++; wp++;
      continue;
    }
    z2 = (int64_t)in[16] * qp[16];
    z3 = (int64_t)in[48] * qp[48];
    z1 = (z2 + z3) * FIX_0_541196100;
    tmp2 = z1 + z3 * (-FIX_1_847759065);
    tmp3 = z1 + z2 * FIX_0_765366865;
    z2 = (int64_t)in[0] * qp[0];
    z3 = (int64_t)in[32] * qp[32];
    tmp0 = (z2 + z3) * (1 << CONST_BITS);
    tmp1 = (z2 - z3) * (1 << CONST_BITS);
    tmp10 = tmp0 + tmp3;
    tmp13 = tmp0 - tmp3;
    tmp11 = tmp1 + tmp2;
    tmp12 = tmp1 - tmp2;

    tmp0 = (int64_t)in[56] * qp[56];
    tmp1 = (int64_t)in[40] * qp[40];
    tmp2 = (int64_t)in[24] * qp[24];
    tmp3 = (int64_t)in[8] * qp[8];
    z1 = tmp0 + tmp3;
    z2 = tmp1 + tmp2;
    z3 = tmp0 + tmp2;
    z4 = tmp1 + tmp3;
    z5 = (z3 + z4) * FIX_1_175875602;
    tmp0 = tmp0 * FIX_0_298631336;
    tmp1 = tmp1 * FIX_2_053119869;
    tmp2 = tmp2 * FIX_3_072711026;
    tmp3 = tmp3 * FIX_1_501321110;
    z1 = z1 * (-FIX_0_899976223);
    z2 = z2 * (-FIX_2_562915447);
    z3 = z3 * (-FIX_1_961570560);
    z4 = z4 * (-FIX_0_390180644);
    z3 += z5;
    z4 += z5;
    tmp0 += z1 + z3;
    tmp1 += z2 + z4;
    tmp2 += z2 + z3;
    tmp3 += z1 + z4;

    wp[0] = (int)DESCALE(tmp10 + tmp3, CONST_BITS - PASS1_BITS);
    wp[56] = (int)DESCALE(tmp10 - tmp3, CONST_BITS - PASS1_BITS);
    wp[8] = (int)DESCALE(tmp11 + tmp2, CONST_BITS - PASS1_BITS);
    wp[48] = (int)DESCALE(tmp11 - tmp2, CONST_BITS - PASS1_BITS);
    wp[16] = (int)DESCALE(tmp12 + tmp1, CONST_BITS - PASS1_BITS);
    wp[40] = (int)DESCALE(tmp12 - tmp1, CONST_BITS - PASS1_BITS);
    wp[24] = (int)DESCALE(tmp13 + tmp0, CONST_BITS - PASS1_BITS);
    wp[32] = (int)DESCALE(tmp13 - tmp0, CONST_BITS - PASS1_BITS);
    in++; qp++; wp++;
  }

  wp = ws;
  for (ctr = 0; ctr < 8; ctr++) {
    uint8_t *o = out + ctr * stride;
    if (wp[1] == 0 && wp[2] == 0 && wp[3] == 0 && wp[4] == 0 &&
        wp[5] == 0 && wp[6] == 0 && wp[7] == 0) {
      uint8_t v = rl[(int)DESCALE((int64_t)wp[0], PASS1_BITS + 3) & 1023];
      o[0] = o[1] = o[2] = o[3] = o[4] = o[5] = o[6] = o[7] = v;
      wp += 8;
      continue;
    }
    z2 = wp[2];
    z3 = wp[6];
    z1 = (z2 + z3) * FIX_0_541196100;
    tmp2 = z1 + z3 * (-FIX_1_847759065);
    tmp3 = z1 + z2 * FIX_0_765366865;
    tmp0 = ((int64_t)wp[0] + (int64_t)wp[4]) * (1 << CONST_BITS);
    tmp1 = ((int64_t)wp[0] - (int64_t)wp[4]) * (1 << CONST_BITS);
    tmp10 = tmp0 + tmp3;
    tmp13 = tmp0 - tmp3;
    tmp11 = tmp1 + tmp2;
    tmp12 = tmp1 - tmp2;

    tmp0 = wp[7];
    tmp1 = wp[5];
    tmp2 = wp[3];
    tmp3 = wp[1];
    z1 = tmp0 + tmp3;
    z2 = tmp1 + tmp2;
    z3 = tmp0 + tmp2;
    z4 = tmp1 + tmp3;
    z5 = (z3 + z4) * FIX_1_175875602;
    tmp0 = tmp0 * FIX_0_298631336;
    tmp1 = tmp1 * FIX_2_053119869;
    tmp2 = tmp2 * FIX_3_072711026;
    tmp3 = tmp3 * FIX_1_501321110;
    z1 = z1 * (-FIX_0_899976223);
    z2 = z2 * (-FIX_2_562915447);
    z3 = z3 * (-FIX_1_961570560);
    z4 = z4 * (-FIX_0_390180644);
    z3 += z5;
    z4 += z5;
    tmp0 += z1 + z3;
    tmp1 += z2 + z4;
    tmp2 += z2 + z3;
    tmp3 += z1 + z4;

#define OUTB(x) rl[(int)DESCALE((x), CONST_BITS + PASS1_BITS + 3) & 1023]
    o[0] = OUTB(tmp10 + tmp3);
    o[7] = OUTB(tmp10 - tmp3);
    o[1] = OUTB(tmp11 + tmp2);
    o[6] = OUTB(tmp11 - tmp2);
    o[2] = OUTB(tmp12 + tmp1);
    o[5] = OUTB(tmp12 - tmp1);
    o[3] = OUTB(tmp13 + tmp0);
    o[4] = OUTB(tmp13 - tmp0);
#undef OUTB
    wp += 8;
  }
}

/* ------------------------------------------------------------------ */
/* setup                                                                */

static int div_round_up(long a, long b) { return (int)((a + b - 1) / b); }

static void initial_setup(jdec *d)
{
  int ci;
  if (d->height > 65500 || d->width > 65500)
    jd_error(d, "Maximum supported image dimension is %u pixels", 65500u);
  if (d->precision != 8)
    jd_error(d, "Unsupported JPEG data precision %d", d->precision);
  d->hmax = d->vmax = 1;
  for (ci = 0; ci < d->ncomp; ci++) {
    jd_comp *c = &d->comp[ci];
    if (c->h <= 0 || c->h > 4 || c->v <= 0 || c->v > 4)
      jd_error(d, "Bogus sampling factors");
    if (c->h > d->hmax) d->hmax = c->h;
    if (c->v > d->vmax) d->vmax = c->v;
  }
  d->mcus_x = div_round_up(d->width, d->hmax * 8);
  d->mcus_y = div_round_up(d->height, d->vmax * 8);
  d->total_imcu_rows = d->mcus_y;
  for (ci = 0; ci < d->ncomp; ci++) {
    jd_comp *c = &d->comp[ci];
    int k;
    c->bw = div_round_up((long)d->width * c->h, d->hmax * 8);
    c->bh = div_round_up((long)d->height * c->v, d->vmax * 8);
    c->dw = div_round_up((long)d->width * c->h, d->hmax);
    c->dh = div_round_up((long)d->height * c->v, d->vmax);
    c->stride = d->mcus_x * c->h * 8;
    c->plane = calloc((size_t)c->stride * (size_t)(d->mcus_y * c->v * 8), 1);
    if (!c->plane)
      jd_error(d, "Insufficient memory (case %d)", 4);
    c->coef = NULL;
    c->qt_latched = 0;
    for (k = 0; k < 64; k++)
      c->coef_bits[k] = -1;
  }
  if (d->scan_ncomp < d->ncomp || d->progressive)
    d->has_multiple_scans = 1;
  else
    d->has_multiple_scans = 0;
}

static void default_decompress_parms(jdec *d)
{
  switch (d->ncomp) {
  case 1:
    d->color_space = CS_GRAY;
    d->out_components = 1;
    break;
  case 3:
    if (d->saw_jfif) {
      d->color_space = CS_YCC;
    } else if (d->saw_adobe) {
      switch (d->adobe_transform) {
      case 0: d->color_space = CS_RGB; break;
      case 1: d->color_space = CS_YCC; break;
      default:
        jd_warn(d, "Unknown Adobe color transform code %d", d->adobe_transform);
        d->color_space = CS_YCC;
        break;
      }
    } else {
      int c0 = d->comp[0].id, c1 = d->comp[1].id, c2 = d->comp[2].id;
      if (c0 == 1 && c1 == 2 && c2 == 3)
        d->color_space = CS_YCC;
      else if (c0 == 82 && c1 == 71 && c2 == 66)
        d->color_space = CS_RGB;
      else
        d->color_space = CS_YCC;
    }
    d->out_components = 3;
    break;
  case 4:
    if (d->saw_adobe) {
      switch (d->adobe_transform) {
      case 0: d->color_space = CS_CMYK; break;
      case 2: d->color_space = CS_YCCK; break;
      default:
        jd_warn(d, "Unknown Adobe color transform code %d", d->adobe_transform);
        d->color_space = CS_YCCK;
        break;
      }
    } else {
      d->color_space = CS_CMYK;
    }
    d->out_components = 4;
    break;
  default:
    d->color_space = 0;
    d->out_components = d->ncomp;
    break;
  }
}

jdec *jd_create(FILE *in)
{
  jdec *d = calloc(1, sizeof(jdec));
  if (!d) {
    fprintf(stderr, "Insufficient memory (case %d)\n", 0);
    exit(1);
  }
  d->in = in;
  d->start_of_file = 1;
  saw_soi = 0;
  if (!sample_range_limit)
    prepare_range_limit();
  return d;
}

void jd_read_header(jdec *d)
{
  int r = read_markers(d);
  if (r == 2) {
    if (d->saw_sof)
      jd_error(d, "Invalid JPEG file structure: missing SOS marker");
    jd_error(d, "JPEG datastream contains no image");
  }
  initial_setup(d);
  default_decompress_parms(d);
}

/* ------------------------------------------------------------------ */
/* scan decoding                                                        */

static void latch_quant(jdec *d)
{
  int i;
  for (i = 0; i < d->scan_ncomp; i++) {
    jd_comp *c = &d->comp[d->scan_comp[i]];
    if (c->qt_latched)
      continue;
    if (c->tq < 0 || c->tq >= 4 || !d->qtab_defined[c->tq])
      jd_error(d, "Quantization table 0x%02x was not defined", c->tq);
    memcpy(c->qt, d->qtab[c->tq], sizeof(c->qt));
    c->qt_latched = 1;
  }
}

static int16_t *coef_block(jd_comp *c, int bx, int by)
{
  return c->coef + ((size_t)by * (size_t)(c->stride / 8) + (size_t)bx) * 64;
}

/* per-scan state */
static int scan_mcus_x, scan_mcus_y;
static int scan_mcu_row;

static void start_scan(jdec *d)
{
  int i;
  latch_quant(d);
  if (d->scan_ncomp == 1) {
    jd_comp *c = &d->comp[d->scan_comp[0]];
    scan_mcus_x = c->bw;
    scan_mcus_y = c->bh;
  } else {
    int blocks = 0;
    scan_mcus_x = d->mcus_x;
    scan_mcus_y = d->mcus_y;
    for (i = 0; i < d->scan_ncomp; i++) {
      jd_comp *c = &d->comp[d->scan_comp[i]];
      blocks += c->h * c->v;
    }
    if (blocks > 10)
      jd_error(d, "Sampling factors too large for interleaved scan");
  }
  if (d->progressive) {
    int bad = 0;
    int is_dc = (d->Ss == 0);
    if (is_dc) {
      if (d->Se != 0) bad = 1;
    } else {
      if (d->Ss > d->Se || d->Se >= 64) bad = 1;
      if (d->scan_ncomp != 1) bad = 1;
    }
    if (d->Ah != 0) {
      if (d->Al != d->Ah - 1) bad = 1;
    }
    if (d->Al > 13) bad = 1;
    if (bad)
      jd_error(d, "Invalid progressive parameters Ss=%d Se=%d Ah=%d Al=%d",
               d->Ss, d->Se, d->Ah, d->Al);
    for (i = 0; i < d->scan_ncomp; i++) {
      int ci = d->scan_comp[i];
      int *cb = d->comp[ci].coef_bits;
      int k;
      if (!is_dc && cb[0] < 0)
        jd_warn(d, "Inconsistent progression sequence for component %d coefficient %d", ci, 0);
      for (k = d->Ss; k <= d->Se; k++) {
        int expected = (cb[k] < 0) ? 0 : cb[k];
        if (d->Ah != expected)
          jd_warn(d, "Inconsistent progression sequence for component %d coefficient %d", ci, k);
        cb[k] = d->Al;
      }
    }
    for (i = 0; i < d->scan_ncomp; i++) {
      jd_comp *c = &d->comp[d->scan_comp[i]];
      if (is_dc) {
        if (d->Ah == 0) {
          if (!d->dc_tab[c->td].defined)
            jd_error(d, "Huffman table 0x%02x was not defined", c->td);
          make_derived(d, &d->dc_tab[c->td], 1);
        }
      } else {
        if (!d->ac_tab[c->ta].defined)
          jd_error(d, "Huffman table 0x%02x was not defined", c->ta);
        make_derived(d, &d->ac_tab[c->ta], 0);
      }
      c->last_dc = 0;
      c->eobrun = 0;
    }
  } else {
    if (d->arith)
      jd_error(d, "Unsupported JPEG process: SOF type 0x%02x", 0xc9);
    if (d->Ss != 0 || d->Se != 63 || d->Ah != 0 || d->Al != 0)
      jd_warn(d, "Invalid SOS parameters for sequential JPEG");
    for (i = 0; i < d->scan_ncomp; i++) {
      jd_comp *c = &d->comp[d->scan_comp[i]];
      if (!d->dc_tab[c->td].defined)
        jd_error(d, "Huffman table 0x%02x was not defined", c->td);
      make_derived(d, &d->dc_tab[c->td], 1);
      if (!d->ac_tab[c->ta].defined)
        jd_error(d, "Huffman table 0x%02x was not defined", c->ta);
      make_derived(d, &d->ac_tab[c->ta], 0);
      c->last_dc = 0;
    }
  }
  d->bits_left = 0;
  gbuf = 0;
  d->insufficient = 0;
  d->restarts_to_go = d->restart_interval;
  scan_mcu_row = 0;
}

/* decode one block, sequential mode */
static void decode_block_seq(jdec *d, jd_comp *c, int16_t *blk)
{
  int s, k, r;
  jd_huff *dc = &d->dc_tab[c->td];
  jd_huff *ac = &d->ac_tab[c->ta];
  s = huff_decode(d, dc);
  if (s) {
    r = get_bits(d, s);
    s = huff_extend(r, s);
  }
  s += c->last_dc;
  c->last_dc = s;
  blk[0] = (int16_t)s;
  for (k = 1; k < 64; k++) {
    s = huff_decode(d, ac);
    r = s >> 4;
    s &= 15;
    if (s) {
      k += r;
      r = get_bits(d, s);
      s = huff_extend(r, s);
      blk[natural_order[k]] = (int16_t)s;
    } else {
      if (r != 15)
        break;
      k += 15;
    }
  }
}

static void decode_dc_first(jdec *d, jd_comp *c, int16_t *blk)
{
  int s, r;
  s = huff_decode(d, &d->dc_tab[c->td]);
  if (s) {
    r = get_bits(d, s);
    s = huff_extend(r, s);
  }
  s += c->last_dc;
  c->last_dc = s;
  blk[0] = (int16_t)(int)((unsigned)s << d->Al);
}

static void decode_dc_refine(jdec *d, int16_t *blk)
{
  int p1 = 1 << d->Al;
  if (get_bits(d, 1))
    blk[0] = (int16_t)(blk[0] | p1);
}

static void decode_ac_first(jdec *d, jd_comp *c, int16_t *blk)
{
  int s, k, r;
  int Se = d->Se, Al = d->Al;
  jd_huff *ac = &d->ac_tab[c->ta];
  if (c->eobrun > 0) {
    c->eobrun--;
    return;
  }
  for (k = d->Ss; k <= Se; k++) {
    s = huff_decode(d, ac);
    r = s >> 4;
    s &= 15;
    if (s) {
      k += r;
      r = get_bits(d, s);
      s = huff_extend(r, s);
      blk[natural_order[k]] = (int16_t)(int)((unsigned)s << Al);
    } else {
      if (r == 15) {
        k += 15;
      } else {
        int eob = 1 << r;
        if (r)
          eob += get_bits(d, r);
        c->eobrun = eob - 1;
        break;
      }
    }
  }
}

static void decode_ac_refine(jdec *d, jd_comp *c, int16_t *blk)
{
  int Se = d->Se;
  int p1 = 1 << d->Al;
  int m1 = (int)((unsigned)-1 << d->Al);
  int s, k, r;
  int eobrun = c->eobrun;
  jd_huff *ac = &d->ac_tab[c->ta];
  k = d->Ss;
  if (eobrun == 0) {
    for (; k <= Se; k++) {
      s = huff_decode(d, ac);
      r = s >> 4;
      s &= 15;
      if (s) {
        if (s != 1)
          jd_warn(d, "Corrupt JPEG data: bad Huffman code");
        if (get_bits(d, 1))
          s = p1;
        else
          s = m1;
      } else {
        if (r != 15) {
          eobrun = 1 << r;
          if (r)
            eobrun += get_bits(d, r);
          break;
        }
      }
      do {
        int16_t *t = blk + natural_order[k];
        if (*t != 0) {
          if (get_bits(d, 1)) {
            if ((*t & p1) == 0) {
              if (*t >= 0)
                *t = (int16_t)(*t + p1);
              else
                *t = (int16_t)(*t + m1);
            }
          }
        } else {
          if (--r < 0)
            break;
        }
        k++;
      } while (k <= Se);
      if (s) {
        int pos = natural_order[k];
        blk[pos] = (int16_t)s;
      }
    }
  }
  if (eobrun > 0) {
    for (; k <= Se; k++) {
      int16_t *t = blk + natural_order[k];
      if (*t != 0) {
        if (get_bits(d, 1)) {
          if ((*t & p1) == 0) {
            if (*t >= 0)
              *t = (int16_t)(*t + p1);
            else
              *t = (int16_t)(*t + m1);
          }
        }
      }
    }
    eobrun--;
  }
  c->eobrun = eobrun;
}

static void decode_block_any(jdec *d, jd_comp *c, int16_t *blk)
{
  if (!d->progressive) {
    decode_block_seq(d, c, blk);
  } else if (d->Ss == 0) {
    if (d->Ah == 0)
      decode_dc_first(d, c, blk);
    else
      decode_dc_refine(d, blk);
  } else {
    if (d->Ah == 0)
      decode_ac_first(d, c, blk);
    else
      decode_ac_refine(d, c, blk);
  }
}

/* Decode one MCU row of the current scan into coefficient buffers
 * (if tobuf) or directly into sample planes. */
static void decode_mcu_row(jdec *d, int tobuf)
{
  int mx, i, bx, by;
  int16_t tmp[64];
  int my = scan_mcu_row;
  for (mx = 0; mx < scan_mcus_x; mx++) {
    if (d->restart_interval) {
      if (d->restarts_to_go == 0)
        process_restart(d);
    }
    if (d->scan_ncomp == 1) {
      jd_comp *c = &d->comp[d->scan_comp[0]];
      int16_t *blk = tobuf ? coef_block(c, mx, my) : tmp;
      if (!tobuf)
        memset(tmp, 0, sizeof(tmp));
      if (!d->insufficient || (d->progressive && d->Ss == 0 && d->Ah != 0))
        decode_block_any(d, c, blk);
      if (!tobuf)
        idct_islow(tmp, c->qt, c->plane + (size_t)my * 8 * c->stride + (size_t)mx * 8, c->stride);
    } else {
      int skip = d->insufficient && !(d->progressive && d->Ss == 0 && d->Ah != 0);
      for (i = 0; i < d->scan_ncomp; i++) {
        jd_comp *c = &d->comp[d->scan_comp[i]];
        for (by = 0; by < c->v; by++) {
          for (bx = 0; bx < c->h; bx++) {
            int gx = mx * c->h + bx, gy = my * c->v + by;
            int16_t *blk = tobuf ? coef_block(c, gx, gy) : tmp;
            if (!tobuf)
              memset(tmp, 0, sizeof(tmp));
            if (!skip)
              decode_block_any(d, c, blk);
            if (!tobuf && gx < c->bw && gy < c->bh)
              idct_islow(tmp, c->qt, c->plane + (size_t)gy * 8 * c->stride + (size_t)gx * 8, c->stride);
          }
        }
      }
    }
    if (d->restart_interval)
      d->restarts_to_go--;
  }
  scan_mcu_row++;
}

static void finish_scan_input(jdec *d)
{
  (void)d;
}

void jd_start_decompress(jdec *d)
{
  int ci;
  d->output_scanline = 0;
  for (ci = 0; ci < d->ncomp; ci++) {
    d->rowbuf[ci] = calloc((size_t)d->comp[ci].stride * (size_t)d->hmax + 16, 1);
  }
  if (d->has_multiple_scans) {
    int r;
    for (ci = 0; ci < d->ncomp; ci++) {
      jd_comp *c = &d->comp[ci];
      size_t nb = (size_t)(c->stride / 8) * (size_t)(d->mcus_y * c->v);
      c->coef = calloc(nb * 64, sizeof(int16_t));
      if (!c->coef)
        jd_error(d, "Insufficient memory (case %d)", 4);
    }
    /* absorb the whole file */
    for (;;) {
      start_scan(d);
      while (scan_mcu_row < scan_mcus_y)
        decode_mcu_row(d, 1);
      finish_scan_input(d);
      r = read_markers(d);
      if (r == 2)
        break;
    }
    d->eoi_reached = 1;
    for (ci = 0; ci < d->ncomp; ci++) {
      jd_comp *c = &d->comp[ci];
      int bx, by;
      if (!c->qt_latched) {
        /* component never appeared in a scan */
        if (c->tq >= 0 && c->tq < 4 && d->qtab_defined[c->tq]) {
          memcpy(c->qt, d->qtab[c->tq], sizeof(c->qt));
        } else {
          jd_error(d, "Quantization table 0x%02x was not defined", c->tq);
        }
      }
      for (by = 0; by < c->bh; by++)
        for (bx = 0; bx < c->bw; bx++)
          idct_islow(coef_block(c, bx, by), c->qt,
                     c->plane + (size_t)by * 8 * c->stride + (size_t)bx * 8, c->stride);
    }
    d->imcu_rows_decoded = d->total_imcu_rows;
  } else {
    start_scan(d);
    d->imcu_rows_decoded = 0;
  }
}

static void ensure_imcu(jdec *d, int row)
{
  if (row >= d->total_imcu_rows)
    row = d->total_imcu_rows - 1;
  while (d->imcu_rows_decoded <= row) {
    decode_mcu_row(d, 0);
    d->imcu_rows_decoded++;
  }
}

/* ------------------------------------------------------------------ */
/* upsampling and color conversion                                     */

static const uint8_t *comp_row(jd_comp *c, int y)
{
  if (y < 0) y = 0;
  if (y >= c->dh) y = c->dh - 1;
  return c->plane + (size_t)y * c->stride;
}

static void upsample_row(jdec *d, int ci, int y, uint8_t *out)
{
  jd_comp *c = &d->comp[ci];
  int hexp = d->hmax / c->h;
  int vexp = d->vmax / c->v;
  int dw = c->dw;
  int x;
  if (c->h == d->hmax && c->v == d->vmax) {
    memcpy(out, comp_row(c, y), (size_t)dw);
    return;
  }
  if (hexp * c->h != d->hmax || vexp * c->v != d->vmax)
    jd_error(d, "Fractional sampling not implemented yet");
  if (hexp == 2 && vexp == 1) {
    const uint8_t *in = comp_row(c, y);
    if (dw > 2) {
      int v;
      v = in[0];
      out[0] = (uint8_t)v;
      out[1] = (uint8_t)((v * 3 + in[1] + 2) >> 2);
      for (x = 1; x < dw - 1; x++) {
        v = in[x] * 3;
        out[2 * x] = (uint8_t)((v + in[x - 1] + 1) >> 2);
        out[2 * x + 1] = (uint8_t)((v + in[x + 1] + 2) >> 2);
      }
      v = in[dw - 1];
      out[2 * (dw - 1)] = (uint8_t)((v * 3 + in[dw - 2] + 1) >> 2);
      out[2 * (dw - 1) + 1] = (uint8_t)v;
    } else {
      for (x = 0; x < dw; x++)
        out[2 * x] = out[2 * x + 1] = in[x];
    }
    return;
  }
  if (hexp == 2 && vexp == 2) {
    int sy = y / 2;
    if (dw > 2) {
      const uint8_t *in0 = comp_row(c, sy);
      const uint8_t *in1 = comp_row(c, (y & 1) ? sy + 1 : sy - 1);
      int thiscol, lastcol, nextcol;
      thiscol = in0[0] * 3 + in1[0];
      nextcol = in0[1] * 3 + in1[1];
      out[0] = (uint8_t)((thiscol * 4 + 8) >> 4);
      out[1] = (uint8_t)((thiscol * 3 + nextcol + 7) >> 4);
      lastcol = thiscol;
      thiscol = nextcol;
      for (x = 1; x < dw - 1; x++) {
        nextcol = in0[x + 1] * 3 + in1[x + 1];
        out[2 * x] = (uint8_t)((thiscol * 3 + lastcol + 8) >> 4);
        out[2 * x + 1] = (uint8_t)((thiscol * 3 + nextcol + 7) >> 4);
        lastcol = thiscol;
        thiscol = nextcol;
      }
      out[2 * (dw - 1)] = (uint8_t)((thiscol * 3 + lastcol + 8) >> 4);
      out[2 * (dw - 1) + 1] = (uint8_t)((thiscol * 4 + 7) >> 4);
    } else {
      const uint8_t *in = comp_row(c, sy);
      for (x = 0; x < dw; x++)
        out[2 * x] = out[2 * x + 1] = in[x];
    }
    return;
  }
  if (hexp == 1 && vexp == 2) {
    int sy = y / 2;
    const uint8_t *in0 = comp_row(c, sy);
    const uint8_t *in1;
    int bias;
    if (y & 1) {
      in1 = comp_row(c, sy + 1);
      bias = 2;
    } else {
      in1 = comp_row(c, sy - 1);
      bias = 1;
    }
    for (x = 0; x < dw; x++)
      out[x] = (uint8_t)((in0[x] * 3 + in1[x] + bias) >> 2);
    return;
  }
  /* generic integral upsampling: replicate */
  {
    const uint8_t *in = comp_row(c, y / vexp);
    int k;
    for (x = 0; x < dw; x++)
      for (k = 0; k < hexp; k++)
        out[x * hexp + k] = in[x];
  }
}

static int ycc_tabs_ready;
static int Cr_r_tab[256], Cb_b_tab[256];
static int32_t Cr_g_tab[256], Cb_g_tab[256];

static void build_ycc_tables(void)
{
  int i;
  const int SCALEBITS = 16;
  const int32_t ONE_HALF = (int32_t)1 << (SCALEBITS - 1);
#define FIXK(x) ((int32_t)((x) * (1L << SCALEBITS) + 0.5))
  for (i = 0; i < 256; i++) {
    int32_t x = i - 128;
    Cr_r_tab[i] = (int)((FIXK(1.40200) * x + ONE_HALF) >> SCALEBITS);
    Cb_b_tab[i] = (int)((FIXK(1.77200) * x + ONE_HALF) >> SCALEBITS);
    Cr_g_tab[i] = (-FIXK(0.71414)) * x;
    Cb_g_tab[i] = (-FIXK(0.34414)) * x + ONE_HALF;
  }
#undef FIXK
  ycc_tabs_ready = 1;
}

/* return the image row index of the last iMCU row needed for output row y */
static int needed_imcu(jdec *d, int y)
{
  int ci;
  int need = y / (d->vmax * 8);
  for (ci = 0; ci < d->ncomp; ci++) {
    jd_comp *c = &d->comp[ci];
    int vexp = d->vmax / c->v;
    if (vexp == 2 && (c->h == d->hmax || (d->hmax / c->h == 2 && c->dw > 2) || d->hmax / c->h == 1)) {
      /* context rows needed: next component row */
      int sy = y / 2 + 1;
      int r;
      if (sy >= c->dh) sy = c->dh - 1;
      r = sy / (c->v * 8);
      if (r > need) need = r;
    }
  }
  return need;
}

void jd_read_scanline(jdec *d, uint8_t *out)
{
  int y = d->output_scanline;
  int ci, x, W = d->width;
  if (y >= d->height)
    return;
  if (!d->has_multiple_scans)
    ensure_imcu(d, needed_imcu(d, y));
  for (ci = 0; ci < d->ncomp; ci++)
    upsample_row(d, ci, y, d->rowbuf[ci]);
  switch (d->color_space) {
  case CS_GRAY:
    memcpy(out, d->rowbuf[0], (size_t)W);
    break;
  case CS_YCC: {
    const uint8_t *Y = d->rowbuf[0], *Cb = d->rowbuf[1], *Cr = d->rowbuf[2];
    if (!ycc_tabs_ready)
      build_ycc_tables();
    for (x = 0; x < W; x++) {
      int yy = Y[x], cb = Cb[x], cr = Cr[x];
      out[3 * x] = sample_range_limit[yy + Cr_r_tab[cr]];
      out[3 * x + 1] = sample_range_limit[yy + (int)((Cb_g_tab[cb] + Cr_g_tab[cr]) >> 16)];
      out[3 * x + 2] = sample_range_limit[yy + Cb_b_tab[cb]];
    }
    break;
  }
  case CS_RGB:
    for (x = 0; x < W; x++) {
      out[3 * x] = d->rowbuf[0][x];
      out[3 * x + 1] = d->rowbuf[1][x];
      out[3 * x + 2] = d->rowbuf[2][x];
    }
    break;
  case CS_CMYK:
    for (x = 0; x < W; x++) {
      out[4 * x] = d->rowbuf[0][x];
      out[4 * x + 1] = d->rowbuf[1][x];
      out[4 * x + 2] = d->rowbuf[2][x];
      out[4 * x + 3] = d->rowbuf[3][x];
    }
    break;
  case CS_YCCK: {
    if (!ycc_tabs_ready)
      build_ycc_tables();
    for (x = 0; x < W; x++) {
      int yy = d->rowbuf[0][x], cb = d->rowbuf[1][x], cr = d->rowbuf[2][x];
      out[4 * x] = sample_range_limit[255 - (yy + Cr_r_tab[cr])];
      out[4 * x + 1] = sample_range_limit[255 - (yy + (int)((Cb_g_tab[cb] + Cr_g_tab[cr]) >> 16))];
      out[4 * x + 2] = sample_range_limit[255 - (yy + Cb_b_tab[cb])];
      out[4 * x + 3] = d->rowbuf[3][x];
    }
    break;
  }
  default:
    for (x = 0; x < W; x++)
      for (ci = 0; ci < d->ncomp; ci++)
        out[d->ncomp * x + ci] = d->rowbuf[ci][x];
    break;
  }
  d->output_scanline++;
}

void jd_finish_decompress(jdec *d)
{
  if (d->eoi_reached)
    return;
  /* read until EOI */
  for (;;) {
    int r = read_markers(d);
    if (r == 2)
      break;
    if (!d->has_multiple_scans)
      jd_error(d, "Bogus JPEG library state");
  }
  d->eoi_reached = 1;
}

void jd_destroy(jdec *d)
{
  int ci;
  for (ci = 0; ci < JD_MAXCOMP; ci++) {
    free(d->comp[ci].plane);
    free(d->comp[ci].coef);
    free(d->rowbuf[ci]);
  }
  free(d);
}
