/* Terminal size lookup through the system termcap emulation (terminfo). */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include "term.h"

typedef int (*tgetent_fn)(char *, const char *);
typedef int (*tgetnum_fn)(const char *);

static void *open_termlib(void)
{
  static const char *names[] = {
    "libtinfo.so.6", "libtinfo.so", "libncursesw.so.6", "libncurses.so.6",
    "libtinfo.so.5", "libncurses.so.5", NULL
  };
  int i;
  for (i = 0; names[i]; i++) {
    void *h = dlopen(names[i], RTLD_NOW | RTLD_GLOBAL);
    if (h)
      return h;
  }
  return NULL;
}

int get_termsize(int *w, int *h, const char **err)
{
  static char errstr[1024];
  static char term_buffer[2048];
  const char *termtype = getenv("TERM");
  void *lib;
  tgetent_fn p_tgetent;
  tgetnum_fn p_tgetnum;
  int i;

  errstr[0] = 0;
  *err = errstr;

  if (!termtype) {
    strcpy(errstr, "Environment variable TERM not set.");
    return -1;
  }

  lib = open_termlib();
  if (lib) {
    p_tgetent = (tgetent_fn)dlsym(lib, "tgetent");
    p_tgetnum = (tgetnum_fn)dlsym(lib, "tgetnum");
  } else {
    p_tgetent = NULL;
    p_tgetnum = NULL;
  }

  if (p_tgetent && p_tgetnum) {
    i = p_tgetent(term_buffer, termtype);
    if (i <= 0) {
      if (i == 0)
        snprintf(errstr, sizeof(errstr) - 1, "Terminal type '%s' not recognized.", termtype);
      else
        strcpy(errstr, "Could not access the termcap data base.");
      return i;
    }
    *w = p_tgetnum("co");
    *h = p_tgetnum("li");
    return 1;
  }

  /* fallback without a terminal library */
  {
    struct winsize ws;
    int cols = 0, lines = 0;
    const char *e;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0) {
      cols = ws.ws_col;
      lines = ws.ws_row;
    }
    if ((e = getenv("LINES")) && atoi(e) > 0)
      lines = atoi(e);
    if ((e = getenv("COLUMNS")) && atoi(e) > 0)
      cols = atoi(e);
    if (cols <= 0)
      cols = 80;
    if (lines <= 0)
      lines = 24;
    *w = cols;
    *h = lines;
    return 1;
  }
}
EOF
echo ok"}

