/* Command line handling. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "options.h"
#include "term.h"

int verbose = 0;
int debug = 0;
int clearscr = 0;
int usecolors = 0;
int colorfill = 0;
int convert_grayscale = 0;
int flipx = 0, flipy = 0;
int html = 0, html_raw = 0, html_bold = 1, html_fontsize = 8;
const char *html_title = "jp2a converted image";
int border = 0;
int invert = 0;
int width = 0, height = 0;
int auto_width = 0, auto_height = 1;
int termfit = TERM_FIT;
int termfit_active = 0;
int term_width = 0, term_height = 0;
char ascii_palette[257] = "   ...',;:clodxkO0KXNWM";
float redweight = 0.2989f, greenweight = 0.5866f, blueweight = 0.1145f;
const char *fileout = NULL;

static const char *version_text =
  "jp2a 1.0.8\n"
  "Copyright 2006-2016 Christian Stigen Larsen\n"
  "Distributed under the GNU General Public License (GPL) v2.\n";

static const char *usage_text =
  "Usage: jp2a [ options ] [ file(s) | URL(s) ]\n"
  "\n"
  "Convert files or URLs from JPEG format to ASCII.\n"
  "\n"
  "OPTIONS\n"
  "  -                 Read images from standard input.\n"
  "      --blue=N.N    Set RGB to grayscale conversion weight, default is 0.1145\n"
  "  -b, --border      Print a border around the output image.\n"
  "      --chars=...   Select character palette used to paint the image.\n"
  "                    Leftmost character corresponds to black pixel, right-\n"
  "                    most to white.  Minimum two characters must be specified.\n"
  "      --clear       Clears screen before drawing each output image.\n"
  "      --colors      Use ANSI colors in output.\n"
  "  -d, --debug       Print additional debug information.\n"
  "      --fill        When used with --color and/or --html, color each character's\n"
  "                    background color.\n"
  "  -x, --flipx       Flip image in X direction.\n"
  "  -y, --flipy       Flip image in Y direction.\n"
  "  -f, --term-fit    Use the largest image dimension that fits in your terminal\n"
  "                    display with correct aspect ratio.\n"
  "      --term-height Use terminal display height.\n"
  "      --term-width  Use terminal display width.\n"
  "  -z, --term-zoom   Use terminal display dimension for output.\n"
  "      --grayscale   Convert image to grayscale when using --html or --colors\n"
  "      --green=N.N   Set RGB to grayscale conversion weight, default is 0.5866\n"
  "      --height=N    Set output height, calculate width from aspect ratio.\n"
  "  -h, --help        Print program help.\n"
  "      --html        Produce strict XHTML 1.0 output.\n"
  "      --html-fill   Same as --fill (will be phased out)\n"
  "      --html-fontsize=N   Set fontsize to N pt, default is 4.\n"
  "      --html-no-bold      Do not use bold characters with HTML output\n"
  "      --html-raw    Output raw HTML codes, i.e. without the <head> section etc.\n"
  "      --html-title=...  Set HTML output title\n"
  "  -i, --invert      Invert output image.  Use if your display has a dark\n"
  "                    background.\n"
  "      --background=dark   These are just mnemonics whether to use --invert\n"
  "      --background=light  or not.  If your console has light characters on\n"
  "                    a dark background, use --background=dark.\n"
  "      --output=...  Write output to file.\n"
  "      --red=N.N     Set RGB to grayscale conversion weight, default 0.2989f.\n"
  "      --size=WxH    Set output width and height.\n"
  "  -v, --verbose     Verbose output.\n"
  "  -V, --version     Print program version.\n"
  "      --width=N     Set output width, calculate height from ratio.\n"
  "\n"
  "  The default mode is `jp2a --term-fit --background=dark'.\n"
  "  See the man-page for jp2a for more detailed help text.\n"
  "\n"
  "Project homepage on https://github.com/cslarsen/jp2a\n"
  "Report bugs to <csl@csl.name>\n";

void print_version(void)
{
  fputs(version_text, stderr);
}

void help(void)
{
  print_version();
  fputc('\n', stderr);
  fputs(usage_text, stderr);
}

static int is(const char *s, const char *a, const char *b)
{
  return !strcmp(s, a) || (b && !strcmp(s, b));
}

void parse_options(int argc, char **argv)
{
  int n, files = 0;

  for (n = 1; n < argc; ++n) {
    const char *s = argv[n];
    int a, b;
    float f;

    if (*s != '-') {
      ++files;
      continue;
    }

    if (!strcmp(s, "-")) { ++files; continue; }
    if (is(s, "-h", "--help")) { help(); exit(0); }
    if (is(s, "-v", "--verbose")) { verbose = 1; continue; }
    if (is(s, "-d", "--debug")) { debug = 1; continue; }
    if (is(s, "--clear", NULL)) { clearscr = 1; continue; }
    if (is(s, "--color", "--colors")) { usecolors = 1; continue; }
    if (is(s, "--fill", NULL)) { colorfill = 1; continue; }
    if (is(s, "--grayscale", NULL)) { usecolors = 1; convert_grayscale = 1; continue; }
    if (is(s, "-x", "--flipx")) { flipx = 1; continue; }
    if (is(s, "-y", "--flipy")) { flipy = 1; continue; }
    if (is(s, "-V", "--version")) { print_version(); exit(0); }
    if (is(s, "--html", NULL)) { html = 1; continue; }
    if (is(s, "--html-fill", NULL)) {
      colorfill = 1;
      fputs("warning: --html-fill has changed to --fill\n", stderr);
      continue;
    }
    if (is(s, "--html-no-bold", NULL)) { html_bold = 0; continue; }
    if (is(s, "--html-raw", NULL)) { html = 1; html_raw = 1; continue; }
    if (is(s, "-b", "--border")) { border = 1; continue; }
    if (is(s, "-i", "--invert")) { invert = !invert; continue; }
    if (is(s, "--background=dark", NULL)) { invert = 0; continue; }
    if (is(s, "--background=light", NULL)) { invert = 1; continue; }
    if (is(s, "-f", "--term-fit")) { termfit = TERM_FIT; continue; }
    if (is(s, "--term-height", NULL)) { termfit = TERM_HEIGHT; continue; }
    if (is(s, "--term-width", NULL)) { termfit = TERM_WIDTH; continue; }
    if (is(s, "-z", "--term-zoom")) { termfit = TERM_ZOOM; continue; }
    if (!strncmp(s, "--html-title=", 13)) { html_title = s + 13; continue; }
    if (sscanf(s, "--width=%d", &a) == 1) { width = a; ++auto_height; continue; }
    if (sscanf(s, "--height=%d", &a) == 1) { height = a; ++auto_width; continue; }
    if (sscanf(s, "--size=%dx%d", &a, &b) == 2) {
      width = a;
      height = b;
      auto_width = auto_height = 0;
      continue;
    }
    if (!strncmp(s, "--chars=", 8)) {
      strcpy(ascii_palette, s + 8);
      continue;
    }
    if (sscanf(s, "--html-fontsize=%d", &a) == 1) { html_fontsize = a; continue; }
    if (!strncmp(s, "--output=", 9)) { fileout = s + 9; continue; }
    if (sscanf(s, "--red=%f", &f) == 1) { redweight = f; continue; }
    if (sscanf(s, "--green=%f", &f) == 1) { greenweight = f; continue; }
    if (sscanf(s, "--blue=%f", &f) == 1) { blueweight = f; continue; }

    fprintf(stderr, "Unknown option %s\n\n", s);
    help();
    exit(1);
  }

  if (!files) {
    fputs("No files specified.\n\n", stderr);
    help();
    exit(1);
  }

  if (termfit != TERM_FIT || (width == 0 && height == 0)) {
    const char *err = "";
    if (get_termsize(&term_width, &term_height, &err) <= 0) {
      fputs(err, stderr);
      fputc('\n', stderr);
      exit(1);
    }
    --term_height;

    switch (termfit) {
    case TERM_ZOOM:
      width = term_width;
      height = term_height;
      auto_width = auto_height = 0;
      break;
    case TERM_WIDTH:
      width = term_width;
      height = 0;
      ++auto_height;
      break;
    case TERM_HEIGHT:
      height = term_height;
      width = 0;
      ++auto_width;
      break;
    default:
      termfit_active = 1;
      if (term_width <= term_height + 1) {
        width = term_width;
        ++auto_height;
      } else {
        height = term_height;
        ++auto_width;
        termfit_active = 2;
      }
      break;
    }
  }

  if (auto_width == 1 && auto_height == 1)
    auto_height = 0;
  else if (auto_width == 2 && auto_height == 1)
    auto_width = auto_height = 0;

  if (strlen(ascii_palette) < 2) {
    fputs("You must specify at least two characters in --chars.\n", stderr);
    exit(1);
  }

  if ((width < 1 && !auto_width) || (height < 1 && !auto_height)) {
    fputs("Invalid width or height specified\n", stderr);
    exit(1);
  }

  if ((redweight + greenweight + blueweight) != 1.0f) {
    fputs("Weights RED + GREEN + BLUE must equal 1.0\n", stderr);
    exit(1);
  }

  if (fileout && !*fileout) {
    fputs("Empty output filename.\n", stderr);
    exit(1);
  }
}
EOF
echo ok"}

