/* Image scaling and ASCII / ANSI / HTML rendering. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include "options.h"
#include "jdec.h"
#include "image.h"

#define ROUND(x) ((int)(0.5f + (float)(x)))

typedef struct {
  int width, height;
  float *pixel, *red, *green, *blue;
  int *yadds;
  float resize_y, resize_x;
  int *lookup_resx;
} Image;

/* the row tracking state survives between images (as in the original) */
static int lasty = 0;

static void out_of_memory(void)
{
  fputs("Not enough memory for given output dimension\n", stderr);
  exit(1);
}

static void *xmalloc(size_t n)
{
  void *p = malloc(n);
  if (!p)
    out_of_memory();
  return p;
}

static size_t isize(int a, int b)
{
  /* emulate int arithmetic wrap-around before conversion to size_t */
  return (size_t)(long)(int)((unsigned)a * (unsigned)b);
}

static void calc_dimensions(int jw, int jh, int *pw, int *ph)
{
  int w = width, h = height;
  int aw = auto_width, ah = auto_height;
#define CALC_WIDTH ROUND(2.0f * (float)h * (float)jw / (float)jh)
#define CALC_HEIGHT ROUND(0.5f * (float)w * (float)jh / (float)jw)
  if (aw && !ah) {
    w = CALC_WIDTH;
    while (w == 0) {
      ++h;
      w = CALC_WIDTH;
    }
    if (termfit_active == 2 && w > term_width) {
      w = term_width;
      aw = 0;
      ah = 1;
    }
  }
  if (!aw && ah) {
    h = CALC_HEIGHT;
    while (h == 0) {
      ++w;
      h = CALC_HEIGHT;
    }
  }
#undef CALC_WIDTH
#undef CALC_HEIGHT
  *pw = w;
  *ph = h;
}

static void malloc_image(Image *i)
{
  i->pixel = i->red = i->green = i->blue = NULL;
  i->yadds = NULL;
  i->lookup_resx = NULL;
  i->pixel = malloc(isize(i->width, i->height) * sizeof(float));
  if (!i->pixel)
    out_of_memory();
  if (usecolors) {
    i->red = malloc(isize(i->width, i->height) * sizeof(float));
    i->green = malloc(isize(i->width, i->height) * sizeof(float));
    i->blue = malloc(isize(i->width, i->height) * sizeof(float));
    if (!i->red || !i->green || !i->blue)
      out_of_memory();
  }
  i->yadds = malloc((size_t)(long)i->height * sizeof(int));
  if (!i->yadds)
    out_of_memory();
  i->lookup_resx = malloc((size_t)(long)(1 + i->width) * sizeof(int));
  if (!i->lookup_resx)
    out_of_memory();
}

static void clear_image(Image *i)
{
  size_t n = isize(i->width, i->height);
  size_t k;
  for (k = 0; k < n; k++) {
    i->pixel[k] = 0.0f;
    if (usecolors)
      i->red[k] = i->green[k] = i->blue[k] = 0.0f;
  }
  for (k = 0; (long)k < (long)i->height; k++)
    i->yadds[k] = 0;
}

static void free_image(Image *i)
{
  free(i->pixel);
  free(i->red);
  free(i->green);
  free(i->blue);
  free(i->yadds);
  free(i->lookup_resx);
}

static void init_image(Image *i, const jdec *d)
{
  int x;
  i->resize_y = (float)(i->height - 1) / (float)(d->height - 1);
  i->resize_x = (float)(d->width - 1) / (float)i->width;
  for (x = 0; x <= i->width; ++x) {
    i->lookup_resx[x] = ROUND((float)x * i->resize_x);
    i->lookup_resx[x] *= d->out_components;
  }
}

static void process_scanline(const jdec *d, const uint8_t *scanline, Image *i)
{
  const int y = ROUND(i->resize_y * (float)(d->output_scanline - 1));
  const int components = d->out_components;

  while (lasty <= y) {
    float *pixel = &i->pixel[(size_t)lasty * (size_t)i->width];
    float *red = NULL, *green = NULL, *blue = NULL;
    int x;
    if (usecolors) {
      red = &i->red[(size_t)lasty * (size_t)i->width];
      green = &i->green[(size_t)lasty * (size_t)i->width];
      blue = &i->blue[(size_t)lasty * (size_t)i->width];
    }
    for (x = 0; x < i->width; ++x) {
      const uint8_t *src = &scanline[i->lookup_resx[x]];
      const uint8_t *src_end = &scanline[i->lookup_resx[x + 1]];
      int adds = 0;
      float v = 0.0f, r = 0.0f, g = 0.0f, b = 0.0f;

      while (src <= src_end) {
        if (components != 3) {
          v += (float)src[0] / 255.0f;
        } else {
          float rr = (float)src[0] / 255.0f;
          float gg = (float)src[1] / 255.0f;
          float bb = (float)src[2] / 255.0f;
          v += rr * redweight + gg * greenweight + bb * blueweight;
          r += rr;
          g += gg;
          b += bb;
        }
        ++adds;
        src += components;
      }

      if (adds > 1) {
        pixel[x] += v / (float)adds;
      } else {
        pixel[x] += v;
      }
      if (usecolors) {
        if (components != 3) {
          /* grayscale sources leave the color channels empty */
        } else if (adds > 1) {
          red[x] += r / (float)adds;
          green[x] += g / (float)adds;
          blue[x] += b / (float)adds;
        } else {
          red[x] += r;
          green[x] += g;
          blue[x] += b;
        }
      }
    }
    ++i->yadds[lasty];
    ++lasty;
  }
  lasty = y;
}

static void normalize(Image *i)
{
  int x, y;
  for (y = 0; y < i->height; ++y) {
    float *pixel = &i->pixel[(size_t)y * (size_t)i->width];
    if (i->yadds[y] > 1) {
      for (x = 0; x < i->width; ++x) {
        pixel[x] /= (float)i->yadds[y];
        if (usecolors) {
          i->red[(size_t)y * i->width + x] /= (float)i->yadds[y];
          i->green[(size_t)y * i->width + x] /= (float)i->yadds[y];
          i->blue[(size_t)y * i->width + x] /= (float)i->yadds[y];
        }
      }
    }
  }
}

static void print_border(int w, FILE *f)
{
  /* mimics a buffer of width+2 dashes framed by '+' characters */
  int n = w + 2, k;
  if (n <= 0) {
    fputc('\n', f);
    return;
  }
  if (n == 1) {
    fputs("+\n", f);
    return;
  }
  fputc('+', f);
  for (k = 1; k < n - 1; k++)
    fputc('-', f);
  fputc('+', f);
  fputc('\n', f);
}

static char palette_char(int idx)
{
  if (idx < 0 || idx >= (int)sizeof(ascii_palette))
    return 0;
  return ascii_palette[idx];
}

static const char *html_entity(char ch)
{
  static char s[2];
  switch (ch) {
  case ' ': return "&nbsp;";
  case '<': return "&lt;";
  case '>': return "&gt;";
  case '&': return "&amp;";
  default:
    s[0] = ch;
    s[1] = 0;
    return s;
  }
}

static void print_html_char(FILE *f, char ch, int rf, int gf, int bf, int rb, int gb, int bb)
{
  if (colorfill)
    fprintf(f, "<span style='color:#%02x%02x%02x; background-color:#%02x%02x%02x;'>%s</span>",
            rf, gf, bf, rb, gb, bb, html_entity(ch));
  else
    fprintf(f, "<span style='color:#%02x%02x%02x;'>%s</span>", rf, gf, bf, html_entity(ch));
}

static void print_image_colors(const Image *i, int chars, FILE *f)
{
  int x, y;
  for (y = 0; y < i->height; ++y) {
    int row = flipy ? i->height - y - 1 : y;
    if (border)
      fputc('|', f);
    for (x = 0; x < i->width; ++x) {
      int col = flipx ? i->width - x - 1 : x;
      size_t idx = (size_t)row * (size_t)i->width + (size_t)col;
      float Y = i->pixel[idx];
      float Y_inv = 1.0f - Y;
      float R = i->red[idx];
      float G = i->green[idx];
      float B = i->blue[idx];
      const int pos = ROUND((float)chars * (!invert ? Y : Y_inv));
      char ch = palette_char(pos);
      const float min = 1.0f / 255.0f;

      if (!html) {
        const float t = 0.1f;
        const float in = 1.0f - t;
        int colr = 0;
        int highl = 0;

        if (Y >= 0.95f && R < min && G < min && B < min)
          highl = 1;

        if (!convert_grayscale) {
          if (R - t > G && R - t > B)
            colr = 31;
          else if (G - t > R && G - t > B)
            colr = 32;
          else if (R - t > B && G - t > B && R + G > in)
            colr = 33;
          else if (B - t > R && B - t > G && Y < 0.95f)
            colr = 34;
          else if (R - t > G && B - t > G && R + B > in)
            colr = 35;
          else if (G - t > R && B - t > R && B + G > in)
            colr = 36;
          else if (R + G + B >= 3.0f * Y)
            colr = 37;
        } else {
          if (Y >= 0.7f) {
            highl = 1;
            colr = 37;
          }
        }

        if (!colr) {
          if (!highl)
            fputc(ch, f);
          else
            fprintf(f, "%c[1m%c%c[0m", 27, ch, 27);
        } else {
          if (colorfill)
            colr += 10;
          fprintf(f, "%c[%dm%c%c[0m", 27, colr, ch, 27);
        }
      } else {
        if (convert_grayscale || (R < min && G < min && B < min && Y > min)) {
          if (colorfill)
            print_html_char(f, ch, ROUND(255.0f * Y * 0.5f), ROUND(255.0f * Y * 0.5f),
                            ROUND(255.0f * Y * 0.5f), ROUND(255.0f * Y), ROUND(255.0f * Y),
                            ROUND(255.0f * Y));
          else
            print_html_char(f, ch, ROUND(255.0f * Y), ROUND(255.0f * Y), ROUND(255.0f * Y),
                            255, 255, 255);
        } else {
          if (colorfill)
            print_html_char(f, ch, ROUND(255.0f * Y * R), ROUND(255.0f * Y * G),
                            ROUND(255.0f * Y * B), ROUND(255.0f * R), ROUND(255.0f * G),
                            ROUND(255.0f * B));
          else
            print_html_char(f, ch, ROUND(255.0f * R), ROUND(255.0f * G), ROUND(255.0f * B),
                            255, 255, 255);
        }
      }
    }
    if (border)
      fputc('|', f);
    if (!html)
      fputc('\n', f);
    else
      fputs("<br/>", f);
  }
}

static void print_image_plain(const Image *i, int chars, FILE *f)
{
  int x, y;
  for (y = 0; y < i->height; ++y) {
    int row = flipy ? i->height - y - 1 : y;
    if (border)
      fputc('|', f);
    for (x = 0; x < i->width; ++x) {
      int col = flipx ? i->width - x - 1 : x;
      float v = i->pixel[(size_t)row * (size_t)i->width + (size_t)col];
      const int pos = ROUND((float)chars * v);
      fputc(palette_char(!invert ? pos : chars - pos), f);
    }
    if (border)
      fputc('|', f);
    fputc('\n', f);
  }
}

static void print_html_start(int fontsize, FILE *f)
{
  fprintf(f,
          "<?xml version='1.0' encoding='ISO-8859-1'?>\n"
          "<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'"
          "  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n"
          "<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n"
          "<head>\n"
          "<title>%s</title>\n"
          "<style type='text/css'>\n"
          "body {\n"
          "%s"
          "}\n"
          ".ascii {\n"
          "   font-family: Courier;\n"
          "%s"
          "   font-size:%dpt;\n"
          "   font-weight: %s;\n"
          "}\n"
          "</style>\n"
          "</head>\n"
          "<body>\n"
          "<div class='ascii'><pre>\n",
          html_title,
          !invert ? "background-color: black;\n" : "   background-color: white;\n",
          usecolors ? "" : (!invert ? "   color: white;\n" : "   color: black;\n"),
          fontsize,
          html_bold ? "bold" : "normal");
}

static void print_html_end(FILE *f)
{
  fputs("</pre>\n</div>\n</body>\n</html>\n", f);
}

static void print_info(const jdec *d, const Image *i)
{
  fprintf(stderr, "Source width: %d\n", d->width);
  fprintf(stderr, "Source height: %d\n", d->height);
  fprintf(stderr, "Source color components: %d\n", d->out_components);
  fprintf(stderr, "Output width: %d\n", i->width);
  fprintf(stderr, "Output height: %d\n", i->height);
  fprintf(stderr, "Output palette (%d chars): '%s'\n", (int)strlen(ascii_palette), ascii_palette);
}

static void print_progress(const jdec *d)
{
  float progress = (float)(d->output_scanline + 1.0f) / (float)d->height;
  int pos = ROUND(54.0f * progress);
  int n;
  fputs("Decompressing image [", stderr);
  for (n = 0; n < pos; ++n)
    fputc('#', stderr);
  for (; n < 54; ++n)
    fputc('.', stderr);
  fputs("]\r", stderr);
  fflush(stderr);
}

void decompress(FILE *fp, FILE *fout)
{
  jdec *d = jd_create(fp);
  Image image;
  uint8_t *row;
  int chars;

  jd_read_header(d);
  jd_start_decompress(d);

  row = malloc((size_t)d->width * (size_t)d->out_components + 16);
  if (!row)
    out_of_memory();

  calc_dimensions(d->width, d->height, &image.width, &image.height);

  malloc_image(&image);
  clear_image(&image);

  if (verbose)
    print_info(d, &image);

  init_image(&image, d);

  while (d->output_scanline < d->height) {
    jd_read_scanline(d, row);
    process_scanline(d, row, &image);
    if (verbose)
      print_progress(d);
  }

  if (verbose)
    fputc('\n', stderr);

  jd_finish_decompress(d);

  normalize(&image);

  if (clearscr)
    fprintf(fout, "%c[2J%c[0;0H", 27, 27);

  if (html && !html_raw)
    print_html_start(html_fontsize, fout);

  if (border)
    print_border(image.width, fout);

  chars = (int)strlen(ascii_palette) - 1;
  if (usecolors)
    print_image_colors(&image, chars, fout);
  else
    print_image_plain(&image, chars, fout);

  if (border)
    print_border(image.width, fout);

  if (html && !html_raw)
    print_html_end(fout);

  free_image(&image);
  free(row);
  jd_destroy(d);
}
