#define ROUND(x) ((int)(0.5f + (float)(x)))

typedef struct {
  int width, height;
  float *pixel, *red, *green, *blue;
  int *yadds;
  float resize_y, resize_x;
  int *lookup_resx;
} Image;

/* the row tracking state survives between images (as in the original) */
static int lasty = 0;

static void out_of_memory(void)
{
  fputs("Not enough memory for given output dimension\n", stderr);
  exit(1);
}

static void *xmalloc(size_t n)
{
  void *p = malloc(n);
  if (!p)
    out_of_memory();
  return p;
}

static size_t isize(int a, int b)
{
  /* emulate int arithmetic wrap-around before conversion to size_t */
  return (size_t)(long)(int)((unsigned)a * (unsigned)b);
}

static void calc_dimensions(int jw, int jh, int *pw, int *ph)
{
  int w = width, h = height;
  int aw = auto_width, ah = auto_height;
#define CALC_WIDTH ROUND(2.0f * (float)h * (float)jw / (float)jh)
#define CALC_HEIGHT ROUND(0.5f * (float)w * (float)jh / (float)jw)
  if (aw && !ah) {
    w = CALC_WIDTH;
    while (w == 0) {
      ++h;
      w = CALC_WIDTH;
    }
    if (termfit_active == 2 && w > term_width) {
      w = term_width;
      aw = 0;
      ah = 1;
    }
  }
  if (!aw && ah) {
    h = CALC_HEIGHT;
    while (h == 0) {
      ++w;
      h = CALC_HEIGHT;
    }
  }
#undef CALC_WIDTH
#undef CALC_HEIGHT
  *pw = w;
  *ph = h;
}

static void malloc_image(Image *i)
{
  i->pixel = i->red = i->green = i->blue = NULL;
  i->yadds = NULL;
  i->lookup_resx = NULL;
  i->pixel = malloc(isize(i->width, i->height) * sizeof(float));
  if (!i->pixel)
    out_of_memory();
  if (usecolors) {
    i->red = malloc(isize(i->width, i->height) * sizeof(float));
    i->green = malloc(isize(i->width, i->height) * sizeof(float));
    i->blue = malloc(isize(i->width, i->height) * sizeof(float));
    if (!i->red || !i->green || !i->blue)
      out_of_memory();
  }
  i->yadds = malloc((size_t)(long)i->height * sizeof(int));
  if (!i->yadds)
    out_of_memory();
  i->lookup_resx = malloc((size_t)(long)(1 + i->width) * sizeof(int));
  if (!i->lookup_resx)
    out_of_memory();
}

static void clear_image(Image *i)
{
  size_t n = isize(i->width, i->height);
  size_t k;
  for (k = 0; k < n; k++) {
    i->pixel[k] = 0.0f;
    if (usecolors)
      i->red[k] = i->green[k] = i->blue[k] = 0.0f;
  }
  for (k = 0; (long)k < (long)i->height; k++)
    i->yadds[k] = 0;
}

static void free_image(Image *i)
{
  free(i->pixel);
  free(i->red);
  free(i->green);
  free(i->blue);
  free(i->yadds);
  free(i->lookup_resx);
}

static void init_image(Image *i, const jdec *d)
{
  int x;
  i->resize_y = (float)(i->height - 1) / (float)(d->height - 1);
  i->resize_x = (float)(d->width - 1) / (float)i->width;
  for (x = 0; x <= i->width; ++x) {
    i->lookup_resx[x] = ROUND((float)x * i->resize_x);
    i->lookup_resx[x] *= d->out_components;
  }
}

static void process_scanline(const jdec *d, const uint8_t *scanline, Image *i)
{
  const int y = ROUND(i->resize_y * (float)(d->output_scanline - 1));
  const int components = d->out_components;

  while (lasty <= y) {
    float *pixel = &i->pixel[(size_t)lasty * (size_t)i->width];
    float *red = NULL, *green = NULL, *blue = NULL;
    int x;
    if (usecolors) {
      red = &i->red[(size_t)lasty * (size_t)i->width];
      green = &i->green[(size_t)lasty * (size_t)i->width];
      blue = &i->blue[(size_t)lasty * (size_t)i->width];
    }
    for (x = 0; x < i->width; ++x) {
      const uint8_t *src = &scanline[i->lookup_resx[x]];
      const uint8_t *src_end = &scanline[i->lookup_resx[x + 1]];
      int adds = 0;
      float v = 0.0f, r = 0.0f, g = 0.0f, b = 0.0f;

      while (src <= src_end) {
        if (components != 3) {
          v += (float)src[0] / 255.0f;
        } else {
          float rr = (float)src[0] / 255.0f;
          float gg = (float)src[1] / 255.0f;
          float bb = (float)src[2] / 255.0f;
          v += rr * redweight + gg * greenweight + bb * blueweight;
          r += rr;
          g += gg;
          b += bb;
        }
        ++adds;
        src += components;
      }

      if (adds > 1) {
        pixel[x] += v / (float)adds;
      } else {
        pixel[x] += v;
      }
      if (usecolors) {
        if (components != 3) {
          /* grayscale sources leave the color channels empty */
        } else if (adds > 1) {
          red[x] += r / (float)adds;
          green[x] += g / (float)adds;
          blue[x] += b / (float)adds;
        } else {
          red[x] += r;
          green[x] += g;
          blue[x] += b;
        }
      }
    }
    ++i->yadds[lasty];
    ++lasty;
  }
  lasty = y;
}

static void normalize(Image *i)
{
  int x, y;
  for (y = 0; y < i->height; ++y) {
    float *pixel = &i->pixel[(size_t)y * (size_t)i->width];
    if (i->yadds[y] > 1) {
      for (x = 0; x < i->width; ++x) {
        pixel[x] /= (float)i->yadds[y];
        if (usecolors) {
          i->red[(size_t)y * i->width + x] /= (float)i->yadds[y];
          i->green[(size_t)y * i->width + x] /= (float)i->yadds[y];
          i->blue[(size_t)y * i->width + x] /= (float)i->yadds[y];
        }
      }
    }
  }
}

static void print_border(int w, FILE *f)
