static void print_image_colors(const Image *i, int chars, FILE *f)
{
  int x, y;
  for (y = 0; y < i->height; ++y) {
    int row = flipy ? i->height - y - 1 : y;
    if (border)
      fputc('|', f);
    for (x = 0; x < i->width; ++x) {
      int col = flipx ? i->width - x - 1 : x;
      size_t idx = (size_t)row * (size_t)i->width + (size_t)col;
      float Y = i->pixel[idx];
      float Y_inv = 1.0f - Y;
      float R = i->red[idx];
      float G = i->green[idx];
      float B = i->blue[idx];
      const int pos = ROUND((float)chars * (!invert ? Y : Y_inv));
      char ch = palette_char(pos);
      const float min = 1.0f / 255.0f;

      if (!html) {
        const float t = 0.1f;
        const float in = 1.0f - t;
        int colr = 0;
        int highl = 0;

        if (Y >= 0.95f && R < min && G < min && B < min)
          highl = 1;

        if (!convert_grayscale) {
          if (R - t > G && R - t > B)
            colr = 31;
          else if (G - t > R && G - t > B)
            colr = 32;
          else if (R - t > B && G - t > B && R + G > in)
            colr = 33;
          else if (B - t > R && B - t > G && Y < 0.95f)
            colr = 34;
          else if (R - t > G && B - t > G && R + B > in)
            colr = 35;
          else if (G - t > R && B - t > R && B + G > in)
            colr = 36;
          else if (R + G + B >= 3.0f * Y)
