FILE *open_url(const char *url, int debug)
{
  int fds[2];
  pid_t pid;

  fflush(stdout);
  fflush(stderr);

  if (pipe(fds) != 0) {
    perror("jp2a: pipe");
    exit(1);
  }

  pid = fork();
  if (pid < 0) {
    perror("jp2a: fork");
    exit(1);
  }

  if (pid == 0) {
    close(fds[0]);
    download(url, fds[1], debug);
    close(fds[1]);
    _exit(0);
  }

  close(fds[1]);
  child_pid = pid;
  return fdopen(fds[0], "rb");
}

void url_finish(void)
{
  if (child_pid > 0) {
    int status;
    waitpid(child_pid, &status, 0);
    child_pid = -1;
  }
}
