/*
 * Downloading of images through libcurl (loaded at run time).
 *
 * As in the original program, the download runs in a forked child process
 * that writes the data into a pipe read by the parent.  The child inherits
 * the parent's (unflushed) stdio buffers and flushes them when it exits.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <dlfcn.h>
#include <sys/types.h>
#include <sys/wait.h>
#include "url.h"

typedef void CURL;
typedef int (*curl_global_init_fn)(long);
typedef CURL *(*curl_easy_init_fn)(void);
typedef int (*curl_easy_setopt_fn)(CURL *, int, ...);
typedef int (*curl_easy_perform_fn)(CURL *);
typedef void (*curl_easy_cleanup_fn)(CURL *);

#define OPT_URL 10002
#define OPT_WRITEDATA 10001
#define OPT_WRITEFUNCTION 20011
#define OPT_VERBOSE 41
#define OPT_FAILONERROR 45
#define OPT_FOLLOWLOCATION 52

static pid_t pending_child = -1;
static volatile sig_atomic_t release_child = 0;

static void on_release(int sig)
{
  (void)sig;
  release_child = 1;
}

static size_t write_cb(void *ptr, size_t size, size_t n, void *userdata)
{
  int fd = *(int *)userdata;
  size_t total = size * n, done = 0;
  while (done < total) {
    ssize_t w = write(fd, (char *)ptr + done, total - done);
    if (w <= 0)
      return 0;
    done += (size_t)w;
  }
  return total;
}

static void download(const char *url, int fd, int debug)
{
  static const char *names[] = { "libcurl.so.4", "libcurl-gnutls.so.4", "libcurl.so", NULL };
  void *lib = NULL;
  int i;
  for (i = 0; names[i] && !lib; i++)
    lib = dlopen(names[i], RTLD_NOW);
  if (lib) {
    curl_global_init_fn g_init = (curl_global_init_fn)dlsym(lib, "curl_global_init");
    curl_easy_init_fn e_init = (curl_easy_init_fn)dlsym(lib, "curl_easy_init");
    curl_easy_setopt_fn e_setopt = (curl_easy_setopt_fn)dlsym(lib, "curl_easy_setopt");
    curl_easy_perform_fn e_perform = (curl_easy_perform_fn)dlsym(lib, "curl_easy_perform");
    curl_easy_cleanup_fn e_cleanup = (curl_easy_cleanup_fn)dlsym(lib, "curl_easy_cleanup");
    if (g_init && e_init && e_setopt && e_perform && e_cleanup) {
      CURL *c;
      g_init(3);
      c = e_init();
      if (c) {
        e_setopt(c, OPT_URL, url);
        e_setopt(c, OPT_VERBOSE, (long)(debug ? 1 : 0));
        e_setopt(c, OPT_WRITEFUNCTION, write_cb);
        e_setopt(c, OPT_WRITEDATA, &fd);
        e_setopt(c, OPT_FAILONERROR, 1L);
        e_setopt(c, OPT_FOLLOWLOCATION, 1L);
        e_perform(c);
        e_cleanup(c);
      }
    }
  }
}

/* let a previous download child terminate (flushing its stdio copies) */
static void release_pending(void)
{
  if (pending_child > 0) {
    int status;
    kill(pending_child, SIGUSR1);
    waitpid(pending_child, &status, 0);
    pending_child = -1;
  }
}

FILE *open_url(const char *url, int debug)
{
  int fds[2];
  pid_t pid, parent;
  struct sigaction sa;

  release_pending();

  memset(&sa, 0, sizeof(sa));
  sa.sa_handler = on_release;
  sigemptyset(&sa.sa_mask);
  sigaction(SIGUSR1, &sa, NULL);

  if (pipe(fds) != 0) {
    perror("jp2a: pipe");
    exit(1);
  }

  parent = getpid();
  pid = fork();
  if (pid < 0) {
    perror("jp2a: fork");
    exit(1);
  }

  if (pid == 0) {
    close(fds[0]);
    download(url, fds[1], debug);
    close(fds[1]);
    /* wait until the parent moves on (or is gone) before exiting */
    while (!release_child && getppid() == parent)
      usleep(2000);
    exit(0);
  }

  close(fds[1]);
  pending_child = pid;
  return fdopen(fds[0], "rb");
}

void url_finish(void)
{
}

void url_next_file(void)
{
  release_pending();
}
