#define BIT_BUF_SIZE 64
#define MIN_GET_BITS (BIT_BUF_SIZE - 7)

static uint64_t gbuf;

/* jpeg_fill_bit_buffer equivalent */
static void fill_bits(jdec *d, int nbits)
{
  if (d->unread_marker == 0) {
    while (d->bits_left < MIN_GET_BITS) {
      int c = read_byte(d);
      if (c == 0xFF) {
        do {
          c = read_byte(d);
        } while (c == 0xFF);
        if (c == 0) {
          c = 0xFF;
        } else {
          d->unread_marker = c;
          goto no_more;
        }
      }
      gbuf = (gbuf << 8) | (uint64_t)c;
      d->bits_left += 8;
    }
    return;
  }
no_more:
  if (nbits > d->bits_left) {
    if (!d->insufficient) {
      jd_warn(d, "Corrupt JPEG data: premature end of data segment");
      d->insufficient = 1;
    }
    gbuf <<= MIN_GET_BITS - d->bits_left;
    d->bits_left = MIN_GET_BITS;
  }
}

static inline int raw_bits(int shift, int n)
{
  return (int)((gbuf >> (shift & 63)) & ((1u << n) - 1));
}

/* CHECK_BIT_BUFFER + GET_BITS */
static inline int get_bits(jdec *d, int n)
{
  if (d->bits_left < n)
    fill_bits(d, n);
  d->bits_left -= n;
  return raw_bits(d->bits_left, n);
}

/* jpeg_huff_decode equivalent */
static int huff_decode_slow(jdec *d, jd_huff *h, int min_bits)
{
  int l = min_bits;
  int32_t code = get_bits(d, l);
  while (code > h->maxcode[l]) {
    code <<= 1;
    code |= get_bits(d, 1);
    l++;
  }
  if (l > 16) {
    jd_warn(d, "Corrupt JPEG data: bad Huffman code");
    return 0;
  }
  return h->vals[(int)(code + h->valoffset[l])];
}

/* HUFF_DECODE equivalent */
static int huff_decode(jdec *d, jd_huff *h)
{
  int nb, look;
  if (d->bits_left < 8) {
    fill_bits(d, 0);
    if (d->bits_left < 8)
      return huff_decode_slow(d, h, 1);
  }
  look = raw_bits(d->bits_left - 8, 8);
  nb = h->lookup[look] >> 8;
  if (nb <= 8) {
    d->bits_left -= nb;
    return h->lookup[look] & 0xFF;
  }
  return huff_decode_slow(d, h, nb);
}

static inline int huff_extend(int r, int s)
{
  return r < (1 << (s - 1)) ? r + (int)((unsigned)-1 << s) + 1 : r;
}

