      *st = (uint8_t)((sv & 0x80) ^ nm);
    } else {
      d->ar_a = qe;
      *st = (uint8_t)((sv & 0x80) ^ nl);
      sv ^= 0x80;
    }
  } else if (d->ar_a < 0x8000L) {
    if (d->ar_a < qe) {
      *st = (uint8_t)((sv & 0x80) ^ nl);
      sv ^= 0x80;
    } else {
      *st = (uint8_t)((sv & 0x80) ^ nm);
    }
  }
  return sv >> 7;
}

static void arith_reset_stats(jdec *d, int restart)
{
  int i;
  for (i = 0; i < d->scan_ncomp; i++) {
    int ci = d->scan_comp[i];
    jd_comp *c = &d->comp[ci];
    if (!d->progressive || (d->Ss == 0 && d->Ah == 0)) {
      if (!restart && (c->td < 0 || c->td >= 4))
        jd_error(d, "Arithmetic table 0x%02x was not defined", c->td);
      memset(d->dc_stats[c->td & 3], 0, 64);
      c->last_dc = 0;
      d->dc_context[ci] = 0;
    }
    if (!d->progressive || d->Ss) {
      if (!restart && (c->ta < 0 || c->ta >= 4))
        jd_error(d, "Arithmetic table 0x%02x was not defined", c->ta);
      memset(d->ac_stats[c->ta & 3], 0, 256);
    }
  }
  d->ar_c = 0;
  d->ar_a = 0;
  d->ar_ct = -16;
  d->restarts_to_go = d->restart_interval;
}

static void arith_process_restart(jdec *d)
{
  read_restart_marker(d);
  arith_reset_stats(d, 1);
}

/* decode a nonzero value's sign/magnitude for DC; returns the difference */
static int arith_dc_diff(jdec *d, jd_comp *c, int ci, int *bad)
{
  int tbl = c->td & 3;
  uint8_t *st = d->dc_stats[tbl] + d->dc_context[ci];
  int sign, m, v;
  *bad = 0;
  if (arith_decode(d, st) == 0) {
    d->dc_context[ci] = 0;
    return 0;
  }
  sign = arith_decode(d, st + 1);
  st += 2;
  st += sign;
  if ((m = arith_decode(d, st)) != 0) {
    st = d->dc_stats[tbl] + 20;
    while (arith_decode(d, st)) {
      if ((m <<= 1) == 0x8000) {
        jd_warn(d, "Corrupt JPEG data: bad arithmetic code");
        d->ar_ct = -1;
        *bad = 1;
        return 0;
      }
      st += 1;
    }
  }
  if (m < (int)((1L << d->arith_dc_L[tbl]) >> 1))
    d->dc_context[ci] = 0;
  else if (m > (int)((1L << d->arith_dc_U[tbl]) >> 1))
    d->dc_context[ci] = 12 + (sign * 4);
  else
    d->dc_context[ci] = 4 + (sign * 4);
  v = m;
  st += 14;
  while (m >>= 1)
    if (arith_decode(d, st))
      v |= m;
  v += 1;
  if (sign)
    v = -v;
  return v;
}

/* decode AC coefficients k = start..end; returns 0 on corrupt data */
static int arith_ac(jdec *d, jd_comp *c, int16_t *blk, int start, int end, int Al)
{
  int tbl = c->ta & 3;
  int k, sign, m, v;
  uint8_t *st;
  for (k = start; k <= end; k++) {
    st = d->ac_stats[tbl] + 3 * (k - 1);
    if (arith_decode(d, st))
      break;
    while (arith_decode(d, st + 1) == 0) {
      st += 3;
      k++;
      if (k > end) {
        jd_warn(d, "Corrupt JPEG data: bad arithmetic code");
        d->ar_ct = -1;
        return 0;
      }
    }
    sign = arith_decode(d, d->fixed_bin);
    st += 2;
    if ((m = arith_decode(d, st)) != 0) {
      if (arith_decode(d, st)) {
        m <<= 1;
        st = d->ac_stats[tbl] + (k <= d->arith_ac_K[tbl] ? 189 : 217);
        while (arith_decode(d, st)) {
          if ((m <<= 1) == 0x8000) {
            jd_warn(d, "Corrupt JPEG data: bad arithmetic code");
            d->ar_ct = -1;
            return 0;
          }
          st += 1;
        }
      }
    }
    v = m;
    st += 14;
    while (m >>= 1)
      if (arith_decode(d, st))
        v |= m;
    v += 1;
    if (sign)
      v = -v;
    blk[natural_order[k]] = (int16_t)(int)((unsigned)v << Al);
  }
  return 1;
}

static void arith_decode_mcu(jdec *d, int16_t **blocks, jd_comp **bcomp, int nblocks)
{
  int b, bad;
  if (d->restart_interval) {
    if (d->restarts_to_go == 0)
      arith_process_restart(d);
    d->restarts_to_go--;
  }

  if (d->progressive && d->Ss == 0 && d->Ah != 0) {
    /* DC refinement */
    int p1 = 1 << d->Al;
    for (b = 0; b < nblocks; b++)
      if (arith_decode(d, d->fixed_bin))
        blocks[b][0] = (int16_t)(blocks[b][0] | p1);
    return;
  }

  if (d->ar_ct == -1)
    return;

  if (!d->progressive) {
    for (b = 0; b < nblocks; b++) {
      jd_comp *c = bcomp[b];
      int ci = (int)(c - d->comp);
      int v = arith_dc_diff(d, c, ci, &bad);
      if (bad)
        return;
      if (v)
        c->last_dc = (c->last_dc + v) & 0xffff;
      blocks[b][0] = (int16_t)c->last_dc;
      if (!arith_ac(d, c, blocks[b], 1, 63, 0))
        return;
    }
    return;
  }

  if (d->Ss == 0) {
    /* DC first */
    for (b = 0; b < nblocks; b++) {
      jd_comp *c = bcomp[b];
      int ci = (int)(c - d->comp);
      int v = arith_dc_diff(d, c, ci, &bad);
      if (bad)
        return;
      c->last_dc += v;
      blocks[b][0] = (int16_t)(int)((unsigned)c->last_dc << d->Al);
    }
    return;
  }

  if (d->Ah == 0) {
    arith_ac(d, bcomp[0], blocks[0], d->Ss, d->Se, d->Al);
    return;
  }

  /* AC refinement */
  {
    jd_comp *c = bcomp[0];
    int16_t *blk = blocks[0];
    int tbl = c->ta & 3;
    int p1 = 1 << d->Al;
    int m1 = (int)((unsigned)-1 << d->Al);
    int k, kex;
    uint8_t *st;
    for (kex = d->Se; kex > 0; kex--)
      if (blk[natural_order[kex]])
        break;
    for (k = d->Ss; k <= d->Se; k++) {
      st = d->ac_stats[tbl] + 3 * (k - 1);
      if (k > kex)
        if (arith_decode(d, st))
          break;
      for (;;) {
        int16_t *t = blk + natural_order[k];
        if (*t) {
          if (arith_decode(d, st + 2)) {
            if (*t < 0)
              *t = (int16_t)(*t + m1);
            else
              *t = (int16_t)(*t + p1);
          }
          break;
        }
        if (arith_decode(d, st + 1)) {
          if (arith_decode(d, d->fixed_bin))
            *t = (int16_t)m1;
          else
            *t = (int16_t)p1;
          break;
        }
        st += 3;
        k++;
        if (k > d->Se) {
          jd_warn(d, "Corrupt JPEG data: bad arithmetic code");
          d->ar_ct = -1;
          return;
        }
      }
    }
  }
}

